/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {LibAppStorage} from "../LibAppStorage.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {LibMinting} from "./LibMinting.sol";
import {C} from "contracts/C.sol";
import {ICumulativePump} from "contracts/interfaces/basin/pumps/ICumulativePump.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Call, IWell} from "contracts/interfaces/basin/IWell.sol";
import {LibWell} from "contracts/libraries/Well/LibWell.sol";
import {LibRedundantMathSigned256} from "contracts/libraries/LibRedundantMathSigned256.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {IBeanstalkWellFunction} from "contracts/interfaces/basin/IBeanstalkWellFunction.sol";
import {IInstantaneousPump} from "contracts/interfaces/basin/pumps/IInstantaneousPump.sol";

/**
 * @title Well Minting Oracle Library
 * @notice Well Minting Oracle can be Checked or Captured to compute
 * the time weighted average Delta B since the last time the Oracle was Captured
 * for a given Well.
 *
 * @dev
 * The Oracle uses the Season timestamp stored in `s.sys.season.timestamp` to determine how many seconds
 * it has been since the last Season instead of storing its own for efficiency purposes.
 * Each Capture stores the encoded cumulative reserves returned by the Pump in `s.wellOracleSnapshots[well]`.
 **/

library LibWellMinting {
    using LibRedundantMathSigned256 for int256;
    using LibRedundantMath256 for uint256;

    uint256 internal constant ZERO_LOOKBACK = 0;

    /**
     * @notice Emitted when a Well Minting Oracle is captured.
     * @param season The season that the Well was captured.
     * @param well The Well that was captured.
     * @param deltaB The time weighted average delta B computed during the Oracle capture.
     * @param cumulativeReserves The encoded cumulative reserves that were snapshotted most by the Oracle capture.
     */
    event WellOracle(uint32 indexed season, address well, int256 deltaB, bytes cumulativeReserves);

    //////////////////// CHECK ////////////////////

    /**
     * @dev Returns the time weighted average delta B in a given Well
     * since the last Sunrise.
     * @return deltaB The time weighted average delta B balance since the last `capture` call.
     */
    function check(address well) external view returns (int256 deltaB) {
        bytes memory lastSnapshot = LibAppStorage.diamondStorage().sys.wellOracleSnapshots[well];
        // If the length of the stored Snapshot for a given Well is 0,
        // then the Oracle is not initialized.
        if (lastSnapshot.length > 0) {
            (deltaB, , , ) = twaDeltaB(well, lastSnapshot);
        }

        deltaB = LibMinting.checkForMaxDeltaB(deltaB);
    }

    //////////////////// CHECK ////////////////////

    /**
     * @dev Returns the time weighted average delta B in a given Well
     * since the last Sunrise and snapshots the current cumulative reserves.
     * @return deltaB The time weighted average delta B balance since the last `capture` call.
     */
    function capture(address well) external returns (int256 deltaB) {
        bytes memory lastSnapshot = LibAppStorage.diamondStorage().sys.wellOracleSnapshots[well];
        // If the length of the stored Snapshot for a given Well is 0,
        // then the Oracle is not initialized.
        if (lastSnapshot.length > 0) {
            deltaB = updateOracle(well, lastSnapshot);
        } else {
            initializeOracle(well);
        }

        deltaB = LibMinting.checkForMaxDeltaB(deltaB);
    }

    //////////////////// Oracle ////////////////////

    /**
     * Initializes the Well Minting Oracle for a given Well by snapshotting the current
     * encoded cumulative reserves from a Beanstalk supported pump.
     */
    function initializeOracle(address well) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // If pump has not been initialized for `well`, `readCumulativeReserves` will revert.
        // Need to handle failure gracefully, so Sunrise does not revert.
        Call[] memory pumps = IWell(well).pumps();
        try ICumulativePump(pumps[0].target).readCumulativeReserves(well, pumps[0].data) returns (
            bytes memory lastSnapshot
        ) {
            s.sys.wellOracleSnapshots[well] = lastSnapshot;
            emit WellOracle(s.sys.season.current, well, 0, lastSnapshot);
        } catch {
            emit WellOracle(s.sys.season.current, well, 0, new bytes(0));
        }
    }

    /**
     * @dev Updates the Oracle snapshot for a given Well and returns the deltaB
     * given the previous snapshot in the Well
     */
    function updateOracle(
        address well,
        bytes memory lastSnapshot
    ) internal returns (int256 deltaB) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256[] memory twaReserves;
        uint256[] memory ratios;
        (deltaB, s.sys.wellOracleSnapshots[well], twaReserves, ratios) = twaDeltaB(
            well,
            lastSnapshot
        );

        // Set the Well reserves in storage, so that it can be read when calculating the
        // twa liquidty of the well when calculating the L2SR.
        // set the USD price of the non bean token so that it can be read when
        // calculating the price of Bean. See {LibEvaluate.evalPrice}.
        LibWell.setTwaReservesForWell(well, twaReserves);
        LibWell.setUsdTokenPriceForWell(well, ratios);
        emit WellOracle(s.sys.season.current, well, deltaB, s.sys.wellOracleSnapshots[well]);
    }

    /**
     * @dev Calculates the delta B of a given well for a given set of well state parameters.
     * Designed to work for instantaneous and twa delta B calculations.
     */
    function getDeltaBInfoFromWell(
        address well,
        uint[] memory reserves,
        bytes memory snapshot,
        uint256 lookback
    ) internal view returns (int256, bytes memory, uint256[] memory, uint256[] memory) {
        // get well tokens
        IERC20[] memory tokens = IWell(well).tokens();
        (uint256[] memory ratios, uint256 beanIndex, bool success) = LibWell.getRatiosAndBeanIndex(
            tokens,
            lookback
        );

        // If the Bean reserve is less than the minimum, the minting oracle should be considered off.
        if (reserves[beanIndex] < C.WELL_MINIMUM_BEAN_BALANCE) {
            return (0, snapshot, new uint256[](0), ratios);
        }

        // If the USD Oracle oracle call fails, the minting oracle should be considered off.
        if (!success) {
            return (0, snapshot, reserves, new uint256[](0));
        }

        int256 deltaB = calculateDeltaBAtBeanIndex(well, reserves, ratios, beanIndex);

        return (deltaB, snapshot, reserves, ratios);
    }

    /**
     * @dev Calculates the delta B at a given Bean index for a given Well address
     * based on the current well reserves, well ratios and well function.
     */
    function calculateDeltaBAtBeanIndex(
        address well,
        uint[] memory reserves,
        uint256[] memory ratios,
        uint256 beanIndex
    ) internal view returns (int256) {
        Call memory wellFunction = IWell(well).wellFunction();
        try
            IBeanstalkWellFunction(wellFunction.target).calcReserveAtRatioSwap(
                reserves,
                beanIndex,
                ratios,
                wellFunction.data
            )
        returns (uint256 reserveAtRatioSwap) {
            return int256(reserveAtRatioSwap).sub(int256(reserves[beanIndex]));
        } catch {
            return 0;
        }
    }

    /**
     * @dev Calculates the time weighted average delta B since the input snapshot for
     * a given Well address.
     */
    function twaDeltaB(
        address well,
        bytes memory lastSnapshot
    ) internal view returns (int256, bytes memory, uint256[] memory, uint256[] memory) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        // Try to call `readTwaReserves` and handle failure gracefully, so Sunrise does not revert.
        // On failure, reset the Oracle by returning an empty snapshot and a delta B of 0.
        Call[] memory pumps = IWell(well).pumps();
        try
            ICumulativePump(pumps[0].target).readTwaReserves(
                well,
                lastSnapshot,
                uint40(s.sys.season.timestamp),
                pumps[0].data
            )
        returns (uint[] memory twaReserves, bytes memory snapshot) {
            // well, reserves, snapshot  lookback
            return (
                getDeltaBInfoFromWell(
                    well,
                    twaReserves,
                    snapshot,
                    block.timestamp.sub(s.sys.season.timestamp)
                )
            );
        } catch {
            // if the pump fails, return all 0s to avoid the sunrise reverting.
            return (0, new bytes(0), new uint256[](0), new uint256[](0));
        }
    }

    /**
     * @dev Calculates the instantaneous delta B for a given Well address.
     * @param well The address of the Well.
     * @return deltaB The instantaneous delta B balance since the last `capture` call.
     */
    function instantaneousDeltaB(address well) internal view returns (int256) {
        Call[] memory pumps = IWell(well).pumps();
        try
            IInstantaneousPump(pumps[0].target).readInstantaneousReserves(well, pumps[0].data)
        returns (uint[] memory instReserves) {
            // if well is not initialized, return 0.
            if (instReserves.length == 0) {
                return 0;
            }
            //                                          well, reserves,   snapshot,  lookback
            (int256 deltaB, , , ) = getDeltaBInfoFromWell(well, instReserves, new bytes(0), 0);
            return (deltaB);
        } catch {
            return 0;
        }
    }
}

contracts/libraries/Oracle/LibChainlinkO.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {IChainlinkAggregator} from "contracts/interfaces/chainlink/IChainlinkAggregator.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";

/**
 * @title Chainlink Oracle Library
 * @notice Contains functionalty to fetch prices from Chainlink price feeds.
 * @dev currently supports:
 * - ETH/USD price feed
 **/
library LibChainlinkOracle {
    using LibRedundantMath256 for uint256;

    uint256 constant PRECISION = 1e6; // use 6 decimal precision.

    // timeout for Oracles with a 1 hour heartbeat.
    uint256 constant FOUR_HOUR_TIMEOUT = 14400;
    // timeout for Oracles with a 1 day heartbeat.
    uint256 constant FOUR_DAY_TIMEOUT = 345600;

    struct TwapVariables {
        uint256 cumulativePrice;
        uint256 endTimestamp;
        uint256 lastTimestamp;
    }

    /**
     * @dev Returns the TOKEN1/TOKEN2, or TOKEN2/TOKEN1 price with the option of using a TWA lookback.
     * Use `lookback = 0` for the instantaneous price. `lookback > 0` for a TWAP.
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if `priceAggregatorAddress` is broken or frozen.
     **/
    function getTokenPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback,
        bool isMillion
    ) internal view returns (uint256 price) {
        return
            lookback > 0
                ? getTwap(priceAggregatorAddress, maxTimeout, tokenDecimals, lookback, isMillion)
                : getPrice(priceAggregatorAddress, maxTimeout, tokenDecimals, isMillion);
    }

    function getTokenPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback
    ) internal view returns (uint256 price) {
        return getTokenPrice(priceAggregatorAddress, maxTimeout, tokenDecimals, lookback, false);
    }

    /**
     * @dev Returns the price of a given `priceAggregator`
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price
     * where TOKEN1 is the numerator asset and TOKEN2 is the asset the oracle is denominated in.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if Chainlink's price feed is broken or frozen.
     **/
    function getPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        bool isMillion
    ) internal view returns (uint256 price) {
        IChainlinkAggregator priceAggregator = IChainlinkAggregator(priceAggregatorAddress);
        // First, try to get current decimal precision:
        uint8 decimals;
        try priceAggregator.decimals() returns (uint8 _decimals) {
            // If call to Chainlink succeeds, record the current decimal precision
            decimals = _decimals;
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }

        // Secondly, try to get latest price data:
        try priceAggregator.latestRoundData() returns (
            uint80 roundId,
            int256 answer,
            uint256 /* startedAt */,
            uint256 timestamp,
            uint80 /* answeredInRound */
        ) {
            // Check for an invalid roundId that is 0
            if (roundId == 0) return 0;
            if (checkForInvalidTimestampOrAnswer(timestamp, answer, block.timestamp, maxTimeout)) {
                return 0;
            }

            // if token decimals is greater than 0, return the TOKEN2/TOKEN1 price instead (i.e invert the price).
            if (tokenDecimals > 0) {
                // if `isMillion` is set, return `MillionTOKEN2/TOKEN1` Price instead
                // (i.e, the amount of TOKEN1 equal to a million of TOKEN2)
                if (isMillion) tokenDecimals = tokenDecimals + 6;
                price = uint256(10 ** (tokenDecimals + decimals)).div(uint256(answer));
            } else {
                // Adjust to 6 decimal precision.
                price = uint256(answer).mul(PRECISION).div(10 ** decimals);
            }
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }
    }

    /**
     * @dev Returns the TWAP price from the Chainlink Oracle over the past `lookback` seconds.
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if Chainlink's price feed is broken or frozen.
     **/
    function getTwap(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback,
        bool isMillion
    ) internal view returns (uint256 price) {
        // First, try to get current decimal precision:
        uint8 decimals;
        try IChainlinkAggregator(priceAggregatorAddress).decimals() returns (uint8 _decimals) {
            // If call to Chainlink succeeds, record the current decimal precision
            decimals = _decimals;
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }

        // Secondly, try to get latest price data:
        try IChainlinkAggregator(priceAggregatorAddress).latestRoundData() returns (
            uint80 roundId,
            int256 answer,
            uint256 /* startedAt */,
            uint256 timestamp,
            uint80 /* answeredInRound */
        ) {
            // Check for an invalid roundId that is 0
            if (roundId == 0) return 0;
            if (checkForInvalidTimestampOrAnswer(timestamp, answer, block.timestamp, maxTimeout)) {
                return 0;
            }

            TwapVariables memory t;

            t.endTimestamp = block.timestamp.sub(lookback);

            if (isMillion) {
                // if `isMillion` flag is enabled,
                tokenDecimals = tokenDecimals + 6;
            }
            // Check if last round was more than `lookback` ago.
            if (timestamp <= t.endTimestamp) {
                if (tokenDecimals > 0) {
                    return uint256(10 ** (tokenDecimals + decimals)).div(uint256(answer));
                } else {
                    // Adjust to 6 decimal precision.
                    return uint256(answer).mul(PRECISION).div(10 ** decimals);
                }
            } else {
                t.lastTimestamp = block.timestamp;
                // Loop through previous rounds and compute cumulative sum until
                // a round at least `lookback` seconds ago is reached.
                while (timestamp > t.endTimestamp) {
                    // if token decimals is greater than 0, return the TOKEN2/TOKEN1 price instead (i.e invert the price).
                    if (tokenDecimals > 0) {
                        answer = int256((10 ** (tokenDecimals + decimals)) / (uint256(answer)));
                    }
                    t.cumulativePrice = t.cumulativePrice.add(
                        uint256(answer).mul(t.lastTimestamp.sub(timestamp))
                    );
                    roundId -= 1;
                    t.lastTimestamp = timestamp;
                    (answer, timestamp) = getRoundData(
                        IChainlinkAggregator(priceAggregatorAddress),
                        roundId
                    );
                    if (
                        checkForInvalidTimestampOrAnswer(
                            timestamp,
                            answer,
                            t.lastTimestamp,
                            maxTimeout
                        )
                    ) {
                        return 0;
                    }
                }
                if (tokenDecimals > 0) {
                    answer = int256((10 ** (tokenDecimals + decimals)) / (uint256(answer)));
                }
                t.cumulativePrice = t.cumulativePrice.add(
                    uint256(answer).mul(t.lastTimestamp.sub(t.endTimestamp))
                );
                if (tokenDecimals > 0) {
                    price = t.cumulativePrice.div(lookback);
                } else {
                    price = t.cumulativePrice.mul(PRECISION).div(10 ** decimals).div(lookback);
                }
            }
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }
    }

    function getRoundData(
        IChainlinkAggregator priceAggregator,
        uint80 roundId
    ) private view returns (int256, uint256) {
        try priceAggregator.getRoundData(roundId) returns (
            uint80 /* roundId */,
            int256 _answer,
            uint256 /* startedAt */,
            uint256 _timestamp,
            uint80 /* answeredInRound */
        ) {
            return (_answer, _timestamp);
        } catch {
            return (-1, 0);
        }
    }

    function checkForInvalidTimestampOrAnswer(
        uint256 timestamp,
        int256 answer,
        uint256 currentTimestamp,
        uint256 maxTimeout
    ) private pure returns (bool) {
        // Check for an invalid timeStamp that is 0, or in the future
        if (timestamp == 0 || timestamp > currentTimestamp) return true;
        // Check if Chainlink's price feed has timed out
        if (currentTimestamp.sub(timestamp) > maxTimeout) return true;
        // Check for non-positive price
        if (answer <= 0) return true;

        return false;
    }
}

contracts/libraries/Oracle/LibDeltaB.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {LibWell} from "../Well/LibWell.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibRedundantMathSigned256} from "contracts/libraries/LibRedundantMathSigned256.sol";
import {Call, IWell} from "contracts/interfaces/basin/IWell.sol";
import {ICappedReservesPump} from "contracts/interfaces/basin/pumps/ICappedReservesPump.sol";
import {IBeanstalkWellFunction} from "contracts/interfaces/basin/IBeanstalkWellFunction.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";

/**
 * @title LibPipelineConvert
 * @author pizzaman1337, Brean
 */

library LibDeltaB {
    using LibRedundantMath256 for uint256;
    using LibRedundantMathSigned256 for int256;

    uint256 internal constant ZERO_LOOKBACK = 0;

    /**
     * @param token The token to get the deltaB of.
     * @return The deltaB of the token, for Bean it returns 0.
     */
    function getCurrentDeltaB(address token) internal view returns (int256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        if (token == s.sys.tokens.bean) {
            return 0;
        }

        int256 deltaB = LibDeltaB.currentDeltaB(token);
        return deltaB;
    }

    /**
     * @dev Calculates the current deltaB for a given Well address.
     * @param well The address of the Well.
     * @return The current deltaB uses the current reserves in the well.
     */
    function currentDeltaB(address well) internal view returns (int256) {
        try IWell(well).getReserves() returns (uint256[] memory reserves) {
            uint256 beanIndex = LibWell.getBeanIndex(IWell(well).tokens());
            // if less than minimum bean balance, return 0, otherwise
            // calculateDeltaBFromReserves will revert
            if (reserves[beanIndex] < C.WELL_MINIMUM_BEAN_BALANCE) {
                return 0;
            }
            return calculateDeltaBFromReserves(well, reserves, ZERO_LOOKBACK);
        } catch {
            return 0;
        }
    }

    /**
     * @notice returns the overall current deltaB for all whitelisted well tokens.
     */
    function overallCurrentDeltaB() internal view returns (int256 deltaB) {
        address[] memory tokens = LibWhitelistedTokens.getWhitelistedWellLpTokens();
        for (uint256 i = 0; i < tokens.length; i++) {
            int256 wellDeltaB = currentDeltaB(tokens[i]);
            deltaB = deltaB.add(wellDeltaB);
        }
    }

    /**
     * @notice returns the overall cappedReserves deltaB for all whitelisted well tokens.
     */
    function cappedReservesDeltaB(address well) internal view returns (int256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        if (well == s.sys.tokens.bean) {
            return 0;
        }

        // get first pump from well
        Call[] memory pumps = IWell(well).pumps();
        address pump = pumps[0].target;

        // well address , data[]
        try ICappedReservesPump(pump).readCappedReserves(well, pumps[0].data) returns (
            uint256[] memory instReserves
        ) {
            uint256 beanIndex = LibWell.getBeanIndex(IWell(well).tokens());
            // if less than minimum bean balance, return 0, otherwise
            // calculateDeltaBFromReserves will revert
            if (instReserves[beanIndex] < C.WELL_MINIMUM_BEAN_BALANCE) {
                return 0;
            }
            // calculate deltaB.
            return calculateDeltaBFromReserves(well, instReserves, ZERO_LOOKBACK);
        } catch {
            return 0;
        }
    }

    // Calculates overall deltaB, used by convert for stalk penalty purposes
    function overallCappedDeltaB() internal view returns (int256 deltaB) {
        address[] memory tokens = LibWhitelistedTokens.getWhitelistedWellLpTokens();
        for (uint256 i = 0; i < tokens.length; i++) {
            int256 cappedDeltaB = cappedReservesDeltaB(tokens[i]);
            deltaB = deltaB.add(cappedDeltaB);
        }
    }

    /**
     * @notice returns the LP supply for each whitelisted well
     */
    function getLpSupply() internal view returns (uint256[] memory lpSupply) {
        address[] memory tokens = LibWhitelistedTokens.getWhitelistedWellLpTokens();
        lpSupply = new uint256[](tokens.length);
        for (uint256 i = 0; i < tokens.length; i++) {
            lpSupply[i] = IERC20(tokens[i]).totalSupply();
        }
    }

    /**
     * @notice returns the overall instantaneous deltaB for all whitelisted well tokens,
     * scaled by the change in LP supply.
     * @dev used in pipelineConvert.
     */
    function scaledOverallCurrentDeltaB(
        uint256[] memory lpSupply
    ) internal view returns (int256 deltaB) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        address[] memory tokens = LibWhitelistedTokens.getWhitelistedWellLpTokens();
        for (uint256 i = 0; i < tokens.length; i++) {
            if (tokens[i] == s.sys.tokens.bean) continue;
            int256 wellDeltaB = scaledCurrentDeltaB(tokens[i], lpSupply[i]);
            deltaB = deltaB.add(wellDeltaB);
        }
    }

    function scaledCurrentDeltaB(
        address well,
        uint256 lpSupply
    ) internal view returns (int256 wellDeltaB) {
        wellDeltaB = currentDeltaB(well);
        if (wellDeltaB == 0) return 0; // prevent divide by zero
        wellDeltaB = scaledDeltaB(lpSupply, IERC20(well).totalSupply(), wellDeltaB);
    }

    /*
     * @notice returns the scaled deltaB, based on LP supply before and after convert
     */
    function scaledDeltaB(
        uint256 beforeLpTokenSupply,
        uint256 afterLpTokenSupply,
        int256 deltaB
    ) internal pure returns (int256) {
        return deltaB.mul(int256(beforeLpTokenSupply)).div(int(afterLpTokenSupply));
    }

    /**
     * @notice calculates the deltaB for a given well using the reserves.
     * @dev reverts if the bean reserve is less than the minimum,
     * or if the usd oracle fails.
     * This differs from the twaDeltaB, as this function should not be used within the sunrise function.
     */
    function calculateDeltaBFromReserves(
        address well,
        uint256[] memory reserves,
        uint256 lookback
    ) internal view returns (int256) {
        IERC20[] memory tokens = IWell(well).tokens();
        Call memory wellFunction = IWell(well).wellFunction();

        (uint256[] memory ratios, uint256 beanIndex, bool success) = LibWell.getRatiosAndBeanIndex(
            tokens,
            lookback
        );

        // Converts cannot be performed, if the Bean reserve is less than the minimum
        if (reserves[beanIndex] < C.WELL_MINIMUM_BEAN_BALANCE) {
            revert("Well: Bean reserve is less than the minimum");
        }

        // If the USD Oracle call fails, a deltaB cannot be determined.
        if (!success) {
            revert("Well: USD Oracle call failed");
        }

        try
            IBeanstalkWellFunction(wellFunction.target).calcReserveAtRatioSwap(
                reserves,
                beanIndex,
                ratios,
                wellFunction.data
            )
        returns (uint256 reserve) {
            return int256(reserve).sub(int256(reserves[beanIndex]));
        } catch {
            return 0;
        }
    }
}

