pragma solidity ^0.8.20;

import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {LibAppStorage} from "../LibAppStorage.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {Deposited, GerminationSide} from "contracts/beanstalk/storage/System.sol";
import {DepositListData} from "contracts/beanstalk/storage/Account.sol";
import {C} from "../../C.sol";
import {LibRedundantMath32} from "contracts/libraries/LibRedundantMath32.sol";
import {LibRedundantMath128} from "contracts/libraries/LibRedundantMath128.sol";
import {LibRedundantMathSigned128} from "contracts/libraries/LibRedundantMathSigned128.sol";
import {LibRedundantMathSigned96} from "contracts/libraries/LibRedundantMathSigned96.sol";
import {LibBytes} from "contracts/libraries/LibBytes.sol";
import {LibGerminate} from "contracts/libraries/Silo/LibGerminate.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibTractor} from "contracts/libraries/LibTractor.sol";

/**
 * @title LibTokenSilo
 * @author Publius, Pizzaman1337
 * @notice Contains functions for depositing, withdrawing and claiming
 * whitelisted Silo tokens.
 *
 * For functionality related to Stalk, and Roots, see {LibSilo}.
 */
library LibTokenSilo {
    using LibRedundantMath256 for uint256;
    using LibRedundantMath128 for uint128;
    using LibRedundantMath32 for uint32;
    using LibRedundantMathSigned128 for int128;
    using SafeCast for int128;
    using SafeCast for uint256;
    using LibRedundantMathSigned96 for int96;

    uint256 constant PRECISION = 1e6; // increased precision from to silo v3.1.

    //////////////////////// ENUM ////////////////////////
    /**
     * @dev when a user deposits or withdraws a deposit, the
     * {TrasferSingle} event is emitted. However, in the case
     * of a transfer, this emission is ommited. This enum is
     * used to determine if the event should be emitted.
     */
    enum Transfer {
        emitTransferSingle,
        noEmitTransferSingle
    }

    //////////////////////// EVENTS ////////////////////////

    /**
     * @dev IMPORTANT: copy of {TokenSilo-AddDeposit}, check there for details.
     */
    event AddDeposit(
        address indexed account,
        address indexed token,
        int96 stem,
        uint256 amount,
        uint256 bdv
    );

    /**
     * @dev IMPORTANT: copy of {TokenSilo-RemoveDeposit}, check there for details.
     */
    event RemoveDeposit(
        address indexed account,
        address indexed token,
        int96 stem,
        uint256 amount,
        uint256 bdv
    );

    // added as the ERC1155 deposit upgrade
    event TransferSingle(
        address indexed operator,
        address indexed sender,
        address indexed recipient,
        uint256 depositId,
        uint256 amount
    );

    //////////////////////// ACCOUNTING: TOTALS GERMINATING ////////////////////////

    /**
     * @notice Increment the total amount and bdv of `token` germinating in the Silo.
     * @dev when an asset is `deposited` in the silo, it is not immediately eliable for
     * bean mints. It must `germinate` (stay deposited the silo) for a certain
     * amount of seasons (the remainer of the current season + 1). This function
     * increments the total amount and bdv germinating in the silo. The {sunrise}
     * function ends the germination process for even or odd germinating deposits.
     *
     * This protects beanstalk from flashloan attacks, and makes `totalDeposited` and
     * `totalDepositedBdv` significantly more MEV resistant.
     */
    function incrementTotalGerminating(
        address token,
        uint256 amount,
        uint256 bdv,
        GerminationSide side
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // verify side is valid
        if (side != GerminationSide.ODD && side != GerminationSide.EVEN) {
            revert("invalid germinationSide"); // should not ever get here
        }

        // increment germinating amount and bdv.
        s.sys.silo.germinating[side][token].amount += amount.toUint128();
        s.sys.silo.germinating[side][token].bdv += bdv.toUint128();

        // emit event.
        emit LibGerminate.TotalGerminatingBalanceChanged(
            LibGerminate.getSeasonGerminationSide() == side
                ? s.sys.season.current
                : s.sys.season.current - 1,
            token,
            int256(amount),
            int256(bdv)
        );
    }

    /**
     * @notice Decrement the total amount and bdv of `token` germinating in the Silo.
     * @dev `decrementTotalGerminating` should be used when removing deposits
     * that are < 2 seasons old.
     */
    function decrementTotalGerminating(
        address token,
        uint256 amount,
        uint256 bdv,
        GerminationSide side
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // verify side is valid
        if (side != GerminationSide.ODD && side != GerminationSide.EVEN) {
            revert("invalid germinationSide"); // should not ever get here
        }

        // decrement germinating amount and bdv.
        s.sys.silo.germinating[side][token].amount -= amount.toUint128();
        s.sys.silo.germinating[side][token].bdv -= bdv.toUint128();

        emit LibGerminate.TotalGerminatingBalanceChanged(
            LibGerminate.getSeasonGerminationSide() == side
                ? s.sys.season.current
                : s.sys.season.current - 1,
            token,
            -int256(amount),
            -int256(bdv)
        );
    }

    /**
     * @notice Increment the total bdv of `token` germinating in the Silo. Used in Enroot.
     */
    function incrementTotalGerminatingBdv(
        address token,
        uint256 bdv,
        GerminationSide side
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        if (side != GerminationSide.ODD && side != GerminationSide.EVEN) {
            revert("invalid germinationSide"); // should not ever get here
        }
        s.sys.silo.germinating[side][token].bdv += bdv.toUint128();

        emit LibGerminate.TotalGerminatingBalanceChanged(
            LibGerminate.getSeasonGerminationSide() == side
                ? s.sys.season.current
                : s.sys.season.current - 1,
            token,
            0,
            int256(bdv)
        );
    }

    //////////////////////// ACCOUNTING: TOTALS ////////////////////////

    /**
     * @dev Increment the total amount and bdv of `token` deposited in the Silo.
     * @dev `IncrementTotalDeposited` should be used when removing deposits that are
     * >= 2 seasons old (ex. when a user converts).
     */
    function incrementTotalDeposited(address token, uint256 amount, uint256 bdv) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();
        s.sys.silo.balances[token].deposited = s.sys.silo.balances[token].deposited.add(
            amount.toUint128()
        );
        s.sys.silo.balances[token].depositedBdv = s.sys.silo.balances[token].depositedBdv.add(
            bdv.toUint128()
        );
    }

    /**
     * @notice Decrement the total amount and bdv of `token` deposited in the Silo.
     * @dev `decrementTotalDeposited` should be used when removing deposits that are
     * >= 2 seasons old.
     */
    function decrementTotalDeposited(address token, uint256 amount, uint256 bdv) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();
        s.sys.silo.balances[token].deposited = s.sys.silo.balances[token].deposited.sub(
            amount.toUint128()
        );
        s.sys.silo.balances[token].depositedBdv = s.sys.silo.balances[token].depositedBdv.sub(
            bdv.toUint128()
        );
    }

    /**
     * @notice Increment the total bdv of `token` deposited in the Silo. Used in Enroot.
     */
    function incrementTotalDepositedBdv(address token, uint256 bdv) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();
        s.sys.silo.balances[token].depositedBdv = s.sys.silo.balances[token].depositedBdv.add(
            bdv.toUint128()
        );
    }

    //////////////////////// ADD DEPOSIT ////////////////////////

    /**
     * @return stalk The amount of Stalk received for this Deposit.
     *
     * @dev Calculate the current BDV for `amount` of `token`, then perform
     * Deposit accounting.
     */
    function deposit(
        address account,
        address token,
        int96 stem,
        uint256 amount
    ) external returns (uint256 stalk, GerminationSide) {
        uint256 bdv = beanDenominatedValue(token, amount);
        return depositWithBDV(account, token, stem, amount, bdv);
    }

    /**
     * @dev Once the BDV received for Depositing `amount` of `token` is known,
     * add a Deposit for `account` and update the total amount Deposited.
     *
     * `s.sys.assetSettings[token].stalkIssuedPerBdv` stores the number of Stalk per BDV for `token`.
     */
    function depositWithBDV(
        address account,
        address token,
        int96 stem,
        uint256 amount,
        uint256 bdv
    ) internal returns (uint256 stalk, GerminationSide side) {
        require(bdv > 0, "Silo: No Beans under Token.");
        AppStorage storage s = LibAppStorage.diamondStorage();

        // determine whether the deposit is odd or even germinating
        side = LibGerminate.getSeasonGerminationSide();

        // all new deposits will increment total germination.
        incrementTotalGerminating(token, amount, bdv, side);

        addDepositToAccount(account, token, stem, amount, bdv, Transfer.emitTransferSingle);

        stalk = bdv.mul(s.sys.silo.assetSettings[token].stalkIssuedPerBdv);
    }

    /**
     * @dev Add `amount` of `token` to a user's Deposit in `stemTipForToken`. Requires a
     * precalculated `bdv`.
     *
     * If a Deposit doesn't yet exist, one is created. Otherwise, the existing
     * Deposit is updated.
     *
     * `amount` & `bdv` are downcasted uint256 -> uint128 to optimize storage cost,
     * since both values can be packed into one slot.
     *
     * Unlike {removeDepositFromAccount}, this function DOES EMIT an
     * {AddDeposit} event. See {removeDepositFromAccount} for more details.
     */
    function addDepositToAccount(
        address account,
        address token,
        int96 stem,
        uint256 amount,
        uint256 bdv,
        Transfer transferType
    ) public {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 depositId = LibBytes.packAddressAndStem(token, stem);

        // add a depositId to an account's depositList, if there is not an existing deposit.
        if (s.accts[account].deposits[depositId].amount == 0 && amount > 0) {
            s.accts[account].depositIdList[token].depositIds.push(depositId);
            s.accts[account].depositIdList[token].idIndex[depositId] =
                s.accts[account].depositIdList[token].depositIds.length -
                1;
        }
        // add amount and bdv to the deposits.
        s.accts[account].deposits[depositId].amount = s
            .accts[account]
            .deposits[depositId]
            .amount
            .add(amount.toUint128());
        s.accts[account].deposits[depositId].bdv = s.accts[account].deposits[depositId].bdv.add(
            bdv.toUint128()
        );

        // Will not overflow b/c crateBDV <= type(uint128).max
        s.accts[account].mowStatuses[token].bdv = s.accts[account].mowStatuses[token].bdv.add(
            bdv.toUint128()
        );

        /**
         *  {addDepositToAccount} is used for both depositing and transferring deposits.
         *  In the case of a deposit, only the {TransferSingle} Event needs to be emitted.
         *  In the case of a transfer, a different {TransferSingle}/{TransferBatch}
         *  Event is emitted in {TokenSilo._transferDeposit(s)},
         *  and thus, this event is ommited.
         */
        if (transferType == Transfer.emitTransferSingle) {
            emit TransferSingle(
                LibTractor._user(), // operator
                address(0), // from
                account, // to
                depositId, // depositID
                amount // token amount
            );
        }
        emit AddDeposit(account, token, stem, amount, bdv);
    }

    //////////////////////// REMOVE DEPOSIT ////////////////////////

    /**
     * @dev Remove `amount` of `token` from a user's Deposit in `stem`.
     *
     * A "Crate" refers to the existing Deposit in storage at:
     *  `s.accts[account].deposits[token][stem]`
     *
     * Partially removing a Deposit should scale its BDV proportionally. For ex.
     * removing 80% of the tokens from a Deposit should reduce its BDV by 80%.
     *
     * During an update, `amount` & `bdv` are cast uint256 -> uint128 to
     * optimize storage cost, since both values can be packed into one slot.
     *
     * This function DOES **NOT** EMIT a {RemoveDeposit} event. This
     * asymmetry occurs because {removeDepositFromAccount} is called in a loop
     * in places where multiple deposits are removed simultaneously, including
     * {TokenSilo-removeDepositsFromAccount} and {TokenSilo-_transferDeposits}.
     */

    function removeDepositFromAccount(
        address account,
        address token,
        int96 stem,
        uint256 amount
    ) internal returns (uint256 crateBDV) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 depositId = LibBytes.packAddressAndStem(token, stem);

        uint256 crateAmount = s.accts[account].deposits[depositId].amount;
        crateBDV = s.accts[account].deposits[depositId].bdv;
        require(amount <= crateAmount, "Silo: Crate balance too low.");

        // Partial remove
        if (amount < crateAmount) {
            // round up removal of BDV. (x - 1)/y + 1
            // https://stackoverflow.com/questions/17944
            uint256 removedBDV = amount.mul(crateBDV).sub(1).div(crateAmount).add(1);
            uint256 updatedBDV = crateBDV.sub(removedBDV);
            uint256 updatedAmount = crateAmount.sub(amount);

            // SafeCast unnecessary b/c updatedAmount <= crateAmount and updatedBDV <= crateBDV,
            // which are both <= type(uint128).max
            s.accts[account].deposits[depositId].amount = uint128(updatedAmount);
            s.accts[account].deposits[depositId].bdv = uint128(updatedBDV);

            s.accts[account].mowStatuses[token].bdv = s.accts[account].mowStatuses[token].bdv.sub(
                uint128(removedBDV)
            );

            return removedBDV;
        }
        // Full remove
        if (crateAmount > 0) {
            delete s.accts[account].deposits[depositId];
            removeDepositIDfromAccountList(account, token, depositId);
        }

        // Will not overflow b/c crateBDV <= type(uint128).max
        s.accts[account].mowStatuses[token].bdv = s.accts[account].mowStatuses[token].bdv.sub(
            uint128(crateBDV)
        );
    }

    //////////////////////// GETTERS ////////////////////////

    /**
     * @dev Calculate the BDV ("Bean Denominated Value") for `amount` of `token`.
     *
     * Makes a call to a BDV function defined in the AssetSettings for this
     * `token`. See {AppStorage.sol:Storage-AssetSettings} for more information.
     */
    function beanDenominatedValue(
        address token,
        uint256 amount
    ) internal view returns (uint256 bdv) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        require(
            s.sys.silo.assetSettings[token].selector != bytes4(0),
            "Silo: Token not whitelisted"
        );

        (bool success, bytes memory data) = address(this).staticcall(
            encodeBdvFunction(
                token,
                s.sys.silo.assetSettings[token].encodeType,
                s.sys.silo.assetSettings[token].selector,
                amount
            )
        );

        if (!success) {
            if (data.length == 0) revert();
            assembly {
                revert(add(32, data), mload(data))
            }
        }

        assembly {
            bdv := mload(add(data, add(0x20, 0)))
        }
    }

    function encodeBdvFunction(
        address token,
        bytes1 encodeType,
        bytes4 selector,
        uint256 amount
    ) internal pure returns (bytes memory callData) {
        if (encodeType == 0x00) {
            callData = abi.encodeWithSelector(selector, amount);
        } else if (encodeType == 0x01) {
            callData = abi.encodeWithSelector(selector, token, amount);
        } else {
            revert("Silo: Invalid encodeType");
        }
    }

    /**
     * @dev Locate the `amount` and `bdv` for a user's Deposit in storage.
     *
     * Silo V3 Deposits are stored within each {Account} as a mapping of:
     *  `uint256 DepositID => { uint128 amount, uint128 bdv }`
     *  The DepositID is the concatination of the token address and the stem.
     *
     * Silo V2 deposits are only usable after a successful migration, see
     * mowAndMigrate within the Migration facet.
     *
     */
    function getDeposit(
        address account,
        address token,
        int96 stem
    ) internal view returns (uint256 amount, uint256 bdv) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 depositId = LibBytes.packAddressAndStem(token, stem);
        amount = s.accts[account].deposits[depositId].amount;
        bdv = s.accts[account].deposits[depositId].bdv;
    }

    /**
     * @dev Get the number of Stalk per BDV per Season for a whitelisted token.
     * 6 decimal precision: 1e10 units = 1 stalk per season
     */
    function stalkEarnedPerSeason(address token) internal view returns (uint256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return uint256(s.sys.silo.assetSettings[token].stalkEarnedPerSeason);
    }

    /**
     * @dev Get the number of Stalk per BDV for a whitelisted token. Formerly just stalk.
     */
    function stalkIssuedPerBdv(address token) internal view returns (uint256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return uint256(s.sys.silo.assetSettings[token].stalkIssuedPerBdv);
    }

    /**
     * @dev returns the cumulative stalk per BDV (stemTip) for a whitelisted token.
     */
    function stemTipForToken(address token) internal view returns (int96 _stemTip) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        // Will not over/underflow because all casted variables are types smaller that int96.
        _stemTip =
            s.sys.silo.assetSettings[token].milestoneStem +
            toInt96(s.sys.silo.assetSettings[token].stalkEarnedPerSeason).mul(
                toInt96(s.sys.season.current).sub(
                    toInt96(s.sys.silo.assetSettings[token].milestoneSeason)
                )
            );
    }

    /**
     * @dev returns the amount of grown stalk a deposit has earned.
     */
    function grownStalkForDeposit(
        address account,
        address token,
        int96 stem
    ) internal view returns (uint256 grownStalk) {
        // stemTipForToken(token) > depositGrownStalkPerBdv for all valid Deposits
        int96 _stemTip = stemTipForToken(token);
        require(stem <= _stemTip, "Silo: Invalid Deposit");
        // The check in the above line guarantees that subtraction result is positive
        // and thus the cast to `uint256` is safe.
        uint256 deltaStemTip = uint256(int256(_stemTip.sub(stem)));
        // no stalk has grown if the stem is equal to the stemTip.
        if (deltaStemTip == 0) return 0;
        (, uint256 bdv) = getDeposit(account, token, stem);

        grownStalk = deltaStemTip.mul(bdv);
    }

    /**
     * @dev returns the amount of grown stalk a deposit would have, based on the stem of the deposit.
     */
    function calculateStalkFromStemAndBdv(
        address token,
        int96 grownStalkIndexOfDeposit,
        uint256 bdv
    ) internal view returns (int96 grownStalk) {
        // current latest grown stalk index
        int96 _stemTipForToken = stemTipForToken(address(token));

        return
            _stemTipForToken.sub(grownStalkIndexOfDeposit).mul(
                SafeCast.toInt96(SafeCast.toInt256(bdv))
            );
    }

    /**
     * @notice returns the grown stalk and germination state of a deposit,
     * based on the amount of grown stalk it has earned.
     */
    function calculateStemForTokenFromGrownStalk(
        address token,
        uint256 grownStalk,
        uint256 bdv
    ) internal view returns (int96 stem, GerminationSide side) {
        LibGerminate.GermStem memory germStem = LibGerminate.getGerminatingStem(token);
        stem = germStem.stemTip.sub(SafeCast.toInt96(SafeCast.toInt256(grownStalk.div(bdv))));
        side = LibGerminate._getGerminationState(stem, germStem);
    }

    function toInt96(uint256 value) internal pure returns (int96) {
        return SafeCast.toInt96(SafeCast.toInt256(value));
    }

    /**
     * @notice removes an depositID from an account's depositID list.
     */
    function removeDepositIDfromAccountList(
        address account,
        address token,
        uint256 depositId
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();
        DepositListData storage list = s.accts[account].depositIdList[token];
        uint256 i = findDepositIdForAccount(account, token, depositId);
        list.depositIds[i] = list.depositIds[list.depositIds.length - 1];
        list.idIndex[list.depositIds[i]] = i;
        list.idIndex[depositId] = type(uint256).max;
        list.depositIds.pop();
    }

    /**
     * @notice given an depositId, find the index of the depositId in the account's deposit list.
     */
    function findDepositIdForAccount(
        address account,
        address token,
        uint256 depositId
    ) internal view returns (uint256 i) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        i = s.accts[account].depositIdList[token].idIndex[depositId];
    }
}

contracts/libraries/Silo/LibWhitelist.so.content:
/*
 SPDX-License-Identifier: MIT
*/

pragma solidity ^0.8.20;

import {C} from "../../C.sol";
import {LibAppStorage} from "../LibAppStorage.sol";
import {Implementation} from "contracts/beanstalk/storage/System.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {AssetSettings} from "contracts/beanstalk/storage/System.sol";
import {LibTokenSilo} from "contracts/libraries/Silo/LibTokenSilo.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibUnripe} from "contracts/libraries/LibUnripe.sol";
import {LibWell, IWell} from "contracts/libraries/Well/LibWell.sol";
import {IChainlinkAggregator} from "contracts/interfaces/chainlink/IChainlinkAggregator.sol";
import {LibRedundantMath32} from "contracts/libraries/LibRedundantMath32.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {IERC20Decimals} from "contracts/libraries/Oracle/LibUsdOracle.sol";

/**
 * @title LibWhitelist
 * @author Publius
 * @notice Handles adding and removing ERC-20 tokens from the Silo Whitelist.
 */
library LibWhitelist {
    using LibRedundantMath32 for uint32;
    using SafeCast for int32;

    /**
     * @notice Emitted when a token is added to the Silo Whitelist.
     * @param token ERC-20 token being added to the Silo Whitelist.
     * @param selector The function selector that returns the BDV of a given token.
     * @param stalkEarnedPerSeason The Stalk per BDV per Season received from depositing `token`.
     * @param stalkIssuedPerBdv The Stalk per BDV given from depositing `token`.
     * @param gaugePoints The gauge points of the token.
     * @param optimalPercentDepositedBdv The target percentage
     * of the total LP deposited BDV for this token.
     */
    event WhitelistToken(
        address indexed token,
        bytes4 selector,
        uint32 stalkEarnedPerSeason,
        uint256 stalkIssuedPerBdv,
        uint128 gaugePoints,
        uint64 optimalPercentDepositedBdv
    );

    /**
     * @notice Emitted when the oracle implementation for a token is updated.
     */
    event UpdatedOracleImplementationForToken(
        address indexed token,
        Implementation oracleImplementation
    );

    /**
     * @notice Emitted when the gauge point implementation for a token is updated.
     */
    event UpdatedGaugePointImplementationForToken(
        address indexed token,
        Implementation gaugePointImplementation
    );

    /**
     * @notice Emitted when the liquidity weight implementation for a token is updated.
     */
    event UpdatedLiquidityWeightImplementationForToken(
        address indexed token,
        Implementation liquidityWeightImplementation
    );

    /**
     * @notice Emitted when the gauge settings are updated.
     * @param token Token that is being updated.
     * @param optimalPercentDepositedBdv The new optimal Percent deposited BDV
     */
    event UpdatedOptimalPercentDepositedBdvForToken(
        address indexed token,
        uint64 optimalPercentDepositedBdv
    );

    /**
     * @notice Emitted when the stalk per bdv per season for a Silo token is updated.
     * @param token ERC-20 token being updated in the Silo Whitelist.
     * @param stalkEarnedPerSeason New stalk per bdv per season value for this token.
     * @param season The season that the new stalk per bdv per season value becomes active (The current season).
     */
    event UpdatedStalkPerBdvPerSeason(
        address indexed token,
        uint32 stalkEarnedPerSeason,
        uint32 season
    );

    /**
     * @notice Emitted when a token is removed from the Silo Whitelist.
     * @param token ERC-20 token being removed from the Silo Whitelist.
     */
    event DewhitelistToken(address indexed token);

    /**
     * @dev Adds an ERC-20 token to the Silo Whitelist.
     * Assumes future tokens will be well pool tokens.
     * Assumes if the gpImplementation and lwImplementation targets are not set,
     * that they are implemented in this diamond.
     * Oracle Implementations may or may not be implemented, depending on the token.
     */
    function whitelistToken(
        address token,
        bytes4 selector,
        uint48 stalkIssuedPerBdv,
        uint32 stalkEarnedPerSeason,
        bytes1 encodeType,
        uint128 gaugePoints,
        uint64 optimalPercentDepositedBdv,
        Implementation memory oracleImplementation,
        Implementation memory gpImplementation,
        Implementation memory lwImplementation
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        // verify the gaugePoint and liquidityWeight selector.
        verifyGaugePointImplementation(gpImplementation);
        verifyLiquidityWeightImplementation(lwImplementation);

        // add whitelist status
        verifyWhitelistStatus(token, selector, stalkIssuedPerBdv);

        // If an LP token, initialize oracle storage variables and set Oracle Implementation:
        if (token != address(s.sys.tokens.bean) && !LibUnripe.isUnripe(token)) {
            s.sys.usdTokenPrice[token] = 1;
            s.sys.twaReserves[token].reserve0 = 1;
            s.sys.twaReserves[token].reserve1 = 1;

            // the Oracle should return the price for the non-bean asset in USD
            address nonBeanToken = address(LibWell.getNonBeanTokenFromWell(token));
            verifyOracleImplementation(nonBeanToken, oracleImplementation);
            s.sys.oracleImplementation[nonBeanToken] = oracleImplementation;
            emit UpdatedOracleImplementationForToken(nonBeanToken, oracleImplementation);
        }

        require(
            s.sys.silo.assetSettings[token].milestoneSeason == 0,
            "Whitelist: Token already whitelisted"
        );
        // beanstalk requires all whitelisted assets to have a minimum stalkEarnedPerSeeason
        // of 1 (due to the germination update). set stalkEarnedPerSeason to 1 to prevent revert.
        if (stalkEarnedPerSeason == 0) stalkEarnedPerSeason = 1;
        s.sys.silo.assetSettings[token].selector = selector;
        s.sys.silo.assetSettings[token].stalkEarnedPerSeason = stalkEarnedPerSeason;
        s.sys.silo.assetSettings[token].stalkIssuedPerBdv = stalkIssuedPerBdv;
        s.sys.silo.assetSettings[token].milestoneSeason = uint32(s.sys.season.current);
        s.sys.silo.assetSettings[token].encodeType = encodeType;
        s.sys.silo.assetSettings[token].gaugePoints = gaugePoints;
        s.sys.silo.assetSettings[token].optimalPercentDepositedBdv = optimalPercentDepositedBdv;
        s.sys.silo.assetSettings[token].gaugePointImplementation = gpImplementation;
        s.sys.silo.assetSettings[token].liquidityWeightImplementation = lwImplementation;

        emit WhitelistToken(
            token,
            selector,
            stalkEarnedPerSeason,
            stalkIssuedPerBdv,
            gaugePoints,
            optimalPercentDepositedBdv
        );

        emit UpdatedGaugePointImplementationForToken(token, gpImplementation);
        emit UpdatedLiquidityWeightImplementationForToken(token, lwImplementation);
    }

    /**
     * @notice Updates gauge settings for token.
     * @dev {LibWhitelistedTokens} must be updated to include the new token.
     */
    function updateGaugeForToken(
        address token,
        uint64 optimalPercentDepositedBdv,
        Implementation memory gpImplementation,
        Implementation memory lwImplementation
    ) internal {
        updateGaugePointImplementationForToken(token, gpImplementation);
        updateLiquidityWeightImplementationForToken(token, lwImplementation);
        updateOptimalPercentDepositedBdvForToken(token, optimalPercentDepositedBdv);
    }

    /**
     * @dev Updates the Stalk per BDV per Season for a token.
     */
    function updateStalkPerBdvPerSeasonForToken(
        address token,
        uint32 stalkEarnedPerSeason
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        require(s.sys.silo.assetSettings[token].milestoneSeason != 0, "Token not whitelisted");

        // beanstalk requires a min. stalkEarnedPerSeason of 1.
        if (stalkEarnedPerSeason == 0) stalkEarnedPerSeason = 1;

        // update milestone stem and season.
        s.sys.silo.assetSettings[token].milestoneStem = LibTokenSilo.stemTipForToken(token);
        s.sys.silo.assetSettings[token].milestoneSeason = s.sys.season.current;

        // stalkEarnedPerSeason is set to int32 before casting down.
        s.sys.silo.assetSettings[token].deltaStalkEarnedPerSeason =
            int32(stalkEarnedPerSeason) -
            int32(s.sys.silo.assetSettings[token].stalkEarnedPerSeason);
        s.sys.silo.assetSettings[token].stalkEarnedPerSeason = stalkEarnedPerSeason;

        emit UpdatedStalkPerBdvPerSeason(token, stalkEarnedPerSeason, s.sys.season.current);
    }

    /**
     * @notice Updates optimalPercentDepositedBdv token.
     * @dev {LibWhitelistedTokens} must be updated to include the new token.
     */
    function updateOptimalPercentDepositedBdvForToken(
        address token,
        uint64 optimalPercentDepositedBdv
    ) internal {
        AssetSettings storage ss = LibAppStorage.diamondStorage().sys.silo.assetSettings[token];
        ss.optimalPercentDepositedBdv = optimalPercentDepositedBdv;
        emit UpdatedOptimalPercentDepositedBdvForToken(token, optimalPercentDepositedBdv);
    }

    /**
     * @notice updates the oracle implementation for a token.
     */
    function updateOracleImplementationForToken(
        address token,
        Implementation memory oracleImplementation
    ) internal {
        // check that new implementation is valid.
        verifyOracleImplementation(token, oracleImplementation);

        AppStorage storage s = LibAppStorage.diamondStorage();
        s.sys.oracleImplementation[token] = oracleImplementation;

        emit UpdatedOracleImplementationForToken(token, oracleImplementation);
    }

    /**
     * @notice updates the gauge point implementation for a token.
     */
    function updateGaugePointImplementationForToken(
        address token,
        Implementation memory gpImplementation
    ) internal {
        AssetSettings storage ss = LibAppStorage.diamondStorage().sys.silo.assetSettings[token];
        require(ss.selector != 0, "Whitelist: Token not whitelisted in Silo");

        // check that new implementation is valid.
        verifyGaugePointImplementation(gpImplementation);

        ss.gaugePointImplementation = gpImplementation;

        emit UpdatedGaugePointImplementationForToken(token, gpImplementation);
    }

    /**
     * @notice updates the gauge point implementation for a token.
     */
    function updateLiquidityWeightImplementationForToken(
        address token,
        Implementation memory lwImplementation
    ) internal {
        AssetSettings storage ss = LibAppStorage.diamondStorage().sys.silo.assetSettings[token];
        require(ss.selector != 0, "Whitelist: Token not whitelisted in Silo");

        // check that new implementation is valid.
        verifyLiquidityWeightImplementation(lwImplementation);

        ss.liquidityWeightImplementation = lwImplementation;

        emit UpdatedLiquidityWeightImplementationForToken(token, lwImplementation);
    }

    /**
     * @notice Removes an ERC-20 token from the Silo Whitelist.
     *
     */
    function dewhitelistToken(address token) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        uint256 tokenStatusIndex = LibWhitelistedTokens.findWhitelistStatusIndex(token);

        // before dewhitelisting, verify that `libWhitelistedTokens` are updated.
        LibWhitelistedTokens.updateWhitelistStatus(
            token,
            false,
            false,
            false,
            s.sys.silo.whitelistStatuses[tokenStatusIndex].isSoppable // if token was soppable, it should remain so, so that previous sops can be claimed.
        );

        // set the stalkEarnedPerSeason to 1 and update milestone stem.
        // stalkEarnedPerSeason requires a min value of 1.
        updateStalkPerBdvPerSeasonForToken(token, 1);

        // delete the selector and encodeType.
        delete s.sys.silo.assetSettings[token].selector;
        delete s.sys.silo.assetSettings[token].encodeType;

        // delete gaugePoints, gaugePointSelector, liquidityWeightSelector, and optimalPercentDepositedBdv.
        delete s.sys.silo.assetSettings[token].gaugePoints;
        delete s.sys.silo.assetSettings[token].gaugePointImplementation;
        delete s.sys.silo.assetSettings[token].liquidityWeightImplementation;
        delete s.sys.silo.assetSettings[token].optimalPercentDepositedBdv;

        // delete implementations:
        delete s.sys.silo.assetSettings[token].gaugePointImplementation;
        delete s.sys.silo.assetSettings[token].liquidityWeightImplementation;

        emit DewhitelistToken(token);
    }

    /**
     * @notice Verifies whether the bdv selector is valid.
     */
    function verifyBDVselector(address token, bytes1 encodeType, bytes4 selector) internal view {
        (bool success, ) = address(this).staticcall(
            LibTokenSilo.encodeBdvFunction(token, encodeType, selector, 0)
        );
        require(success, "Whitelist: Invalid BDV selector");
    }

    /**
     * @notice Verifies whether a gaugePointSelector at an external contract
     * is valid for the gauge system.
     */
    function verifyOracleImplementation(
        address token,
        Implementation memory oracleImplementation
    ) internal {
        bool success;
        bytes memory returnData;
        // if the encode type is 0x01, verify using the chainlink implementation.
        if (oracleImplementation.encodeType == bytes1(0x01)) {
            (success, returnData) = oracleImplementation.target.staticcall(
                abi.encodeWithSelector(IChainlinkAggregator.decimals.selector)
            );
        } else if (oracleImplementation.encodeType == bytes1(0x02)) {
            // 0x0dfe1681 == token0() for uniswap pools.
            (success, returnData) = oracleImplementation.target.staticcall(
                abi.encodeWithSelector(0x0dfe1681)
            );
        } else {
            // external oracles must have a target address
            require(oracleImplementation.target != address(0), "Whitelist: Invalid Target Address");

            // verify you passed in a callable oracle selector
            (success, returnData) = oracleImplementation.target.call(
                abi.encodeWithSelector(
                    oracleImplementation.selector,
                    IERC20Decimals(token).decimals(),
                    0,
                    oracleImplementation.data
                )
            );
        }
        require(success && returnData.length > 0, "Whitelist: Invalid Oracle Implementation");
    }

    /**
     * @notice Verifies whether a gaugePointSelector at an external contract
     * is valid for the gauge system.
     */
    function verifyGaugePointImplementation(Implementation memory gpImplementation) internal view {
        // if the target is not set, assume the gaugePoint implementation is in this diamond.
        address target = gpImplementation.target == address(0)
            ? address(this)
            : gpImplementation.target;
        // verify you passed in a callable gaugePoint selector
        (bool success, bytes memory returnData) = target.staticcall(
            abi.encodeWithSelector(gpImplementation.selector, 0, 0, 0, gpImplementation.data)
        );
        require(success && returnData.length > 0, "Whitelist: Invalid GaugePoint Implementation");
    }

    /**
     * @notice Verifies whether liquidityWeight selector at an external contract
     * is valid for the gauge system.
     */
    function verifyLiquidityWeightImplementation(Implementation memory lw) internal view {
        // if the target is not set, assume the liquidity weight implementation is in this diamond.
        address target = lw.target == address(0) ? address(this) : lw.target;
        // verify you passed in a callable liquidityWeight selector
        (bool success, bytes memory returnData) = target.staticcall(
            abi.encodeWithSelector(lw.selector, lw.data)
        );
        require(
            success && returnData.length > 0,
            "Whitelist: Invalid LiquidityWeight Implementation"
        );
    }

    /**
     * @notice verifies whether a token is not whitelisted.
     * @dev if the token has been previously whitelisted,
     * return the current stalk issued per bdv.
     */
    function verifyWhitelistStatus(
        address token,
        bytes4 selector,
        uint48 stalkIssuedPerBdv
    ) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();

        (bool isWhitelisted, bool previouslyWhitelisted) = LibWhitelistedTokens.checkWhitelisted(
            token
        );
        require(isWhitelisted == false, "Whitelist: Token already whitelisted");

        // add whitelist status. If previously whitelisted, update the status rather than appending.
        if (previouslyWhitelisted) {
            LibWhitelistedTokens.updateWhitelistStatus(
                token,
                true, // Whitelisted by default.
                token != address(s.sys.tokens.bean) && !LibUnripe.isUnripe(token), // Assumes tokens that are not Unripe and not Bean are LP tokens.
                selector == LibWell.WELL_BDV_SELECTOR,
                selector == LibWell.WELL_BDV_SELECTOR // Assumes wells are soppable if selector is WELL_BDV_SELECTOR
            );
        } else {
            // assumes new tokens are well pool tokens.
            LibWhitelistedTokens.addWhitelistStatus(
                token,
                true, // Whitelisted by default.
                token != address(s.sys.tokens.bean) && !LibUnripe.isUnripe(token), // Assumes tokens that are not Unripe and not Bean are LP tokens.
                selector == LibWell.WELL_BDV_SELECTOR,
                selector == LibWell.WELL_BDV_SELECTOR // Assumes wells are soppable if selector is WELL_BDV_SELECTOR
            );
        }

        // if the token has previously been whitelisted, the stalkIssuedPerBdv
        // cannot be updated, as previous deposits would have been made with the
        // previous value.
        if (previouslyWhitelisted) {
            require(
                s.sys.silo.assetSettings[token].stalkIssuedPerBdv == stalkIssuedPerBdv,
                "Whitelist: Cannot update stalkIssuedPerBdv"
            );
        }
    }
}

