pragma solidity ^0.8.20;

import "./interfaces/IBean.sol";
import "./interfaces/IFertilizer.sol";
import "./interfaces/IProxyAdmin.sol";
import "./libraries/Decimal.sol";
import "./interfaces/IPipeline.sol";

/**
 * @title C
 * @author Publius
 * @notice Contains constants used throughout Beanstalk.
 */
library C {
    using Decimal for Decimal.D256;

    //////////////////// Globals ////////////////////

    uint256 internal constant PRECISION = 1e18;

    //////////////////// Reentrancy ////////////////////
    uint256 internal constant NOT_ENTERED = 1;
    uint256 internal constant ENTERED = 2;

    //////////////////// Season ////////////////////

    /// @dev The length of a Season meaured in seconds.
    uint256 internal constant CURRENT_SEASON_PERIOD = 3600; // 1 hour
    uint256 internal constant SOP_PRECISION = 1e30;

    //////////////////// Silo ////////////////////
    uint256 internal constant STALK_PER_BEAN = 1e10;
    uint256 private constant ROOTS_BASE = 1e12;

    //////////////////// Exploit Migration ////////////////////

    uint256 private constant UNRIPE_LP_PER_DOLLAR = 1884592; // 145_113_507_403_282 / 77_000_000
    uint256 private constant ADD_LP_RATIO = 866616;

    //////////////////// Contracts ////////////////////

    address internal constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address internal constant PIPELINE = 0xb1bE000644bD25996b0d9C2F7a6D6BA3954c91B0;

    //////////////////// Well ////////////////////

    uint256 internal constant WELL_MINIMUM_BEAN_BALANCE = 1000_000_000; // 1,000 Beans

    //////////////////// Tractor ////////////////////

    uint80 internal constant SLOT_SIZE = 32;
    // Special index to indicate the data to copy is the publisher address.
    uint80 internal constant PUBLISHER_COPY_INDEX = type(uint80).max;
    // Special index to indicate the data to copy is the operator address.
    uint80 internal constant OPERATOR_COPY_INDEX = type(uint80).max - 1;

    function getRootsBase() internal pure returns (uint256) {
        return ROOTS_BASE;
    }

    function unripeLPPerDollar() internal pure returns (uint256) {
        return UNRIPE_LP_PER_DOLLAR;
    }

    function dollarPerUnripeLP() internal pure returns (uint256) {
        return 1e12 / UNRIPE_LP_PER_DOLLAR;
    }

    function exploitAddLPRatio() internal pure returns (uint256) {
        return ADD_LP_RATIO;
    }

    function precision() internal pure returns (uint256) {
        return PRECISION;
    }

    function pipeline() internal pure returns (IPipeline) {
        return IPipeline(PIPELINE);
    }
}

contracts/beanstalk/ReentrancyGuard.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {AppStorage} from "./storage/AppStorage.sol";
import {C} from "contracts/C.sol";

/**
 * @author Beanstalk Farms
 * @title Variation of Oepn Zeppelins reentrant guard to include Beanstalk specific functionality.
 * https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts%2Fsecurity%2FReentrancyGuard.sol
 *
 * The key difference between Beanstalk reentrancy and standard reentrancy is the need for Beanstalk
 * to be able to re-enter itself executing functions through farm-like functions. This Farm functiiionality
 * allows users to batch multiple Beanstalk functions into a single transaction.
 * Examples of Farm use can be seen in Farm, AdvancedFarm, Tractor, and PipelineConvert.
 * Reference _beanstalkCall() to see Farm interaction with ReentrancyGuard.
 **/
abstract contract ReentrancyGuard {
    AppStorage internal s;

    /**
     * @notice Verify Beanstalk is not already entered and lock entrance.
     * @dev Standard reentrancy is not compatible with farm-like features.
     */
    modifier nonReentrant() {
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }

    /**
     * @notice Verify and lock both standard entrance and farming entrance.
     * @dev This modifier should be used on all functions that contain generalized Farm calls.
     */
    modifier nonReentrantFarm() {
        require(s.sys.farmingStatus != C.ENTERED, "ReentrancyGuard: reentrant farm call");
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.farmingStatus = C.ENTERED;
        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.farmingStatus = C.NOT_ENTERED;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }
}

