/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {LibTractor} from "./LibTractor.sol";

/**
 * @title LibBytes
 * @notice LibBytes offers utility functions for managing data at the Byte level.
 */
library LibBytes {
    /*
     * @notice From Solidity Bytes Arrays Utils
     * @author Gonçalo Sá <goncalo.sa@consensys.net>
     */
    function toUint8(bytes memory _bytes, uint256 _start) internal pure returns (uint8) {
        require(_start + 1 >= _start, "toUint8_overflow");
        require(_bytes.length >= _start + 1, "toUint8_outOfBounds");
        uint8 tempUint;

        assembly {
            tempUint := mload(add(add(_bytes, 0x1), _start))
        }

        return tempUint;
    }

    /*
     * @notice From Solidity Bytes Arrays Utils
     * @author Gonçalo Sá <goncalo.sa@consensys.net>
     */
    function toUint32(bytes memory _bytes, uint256 _start) internal pure returns (uint32) {
        require(_start + 4 >= _start, "toUint32_overflow");
        require(_bytes.length >= _start + 4, "toUint32_outOfBounds");
        uint32 tempUint;

        assembly {
            tempUint := mload(add(add(_bytes, 0x4), _start))
        }

        return tempUint;
    }

    function toUint80(bytes memory _bytes, uint256 _start) internal pure returns (uint80) {
        require(_start + 10 >= _start, "toUint32_overflow");
        require(_bytes.length >= _start + 10, "toUint32_outOfBounds");
        uint80 tempUint;

        assembly {
            tempUint := mload(add(add(_bytes, 0xA), _start))
        }

        return tempUint;
    }

    /*
     * @notice From Solidity Bytes Arrays Utils
     * @author Gonçalo Sá <goncalo.sa@consensys.net>
     */
    function toUint256(bytes memory _bytes, uint256 _start) internal pure returns (uint256) {
        require(_start + 32 >= _start, "toUint256_overflow");
        require(_bytes.length >= _start + 32, "toUint256_outOfBounds");
        uint256 tempUint;

        assembly {
            tempUint := mload(add(add(_bytes, 0x20), _start))
        }

        return tempUint;
    }

    function toBytes32(bytes memory _bytes, uint256 _start) internal pure returns (bytes32) {
        require(_start + 32 >= _start, "toBytes32_overflow");
        require(_bytes.length >= _start + 32, "toBytes32_outOfBounds");
        bytes32 tempBytes32;

        assembly {
            tempBytes32 := mload(add(add(_bytes, 0x20), _start))
        }

        return tempBytes32;
    }

    /**
     * @notice slices bytes memory
     * @param b The memory bytes array to load from
     * @param start The start of the slice
     * @return sliced bytes
     */
    function sliceFrom(bytes memory b, uint256 start) internal pure returns (bytes memory) {
        uint256 length = b.length - start;
        bytes memory memBytes = new bytes(length);
        for (uint256 i = 0; i < length; ++i) {
            memBytes[i] = b[start + i];
        }
        return memBytes;
    }

    /**
     * @notice Loads a slice of a calldata bytes array into memory
     * @param b The calldata bytes array to load from
     * @param start The start of the slice
     * @param length The length of the slice
     */
    function sliceToMemory(
        bytes calldata b,
        uint256 start,
        uint256 length
    ) internal pure returns (bytes memory) {
        bytes memory memBytes = new bytes(length);
        for (uint256 i = 0; i < length; ++i) {
            memBytes[i] = b[start + i];
        }
        return memBytes;
    }

    /**
     * @notice Copy 32 Bytes from copyFromData at copyIndex and paste into pasteToData at pasteIndex
     * @param copyFromData The data bytes to copy from
     * @param pasteToData The data bytes to paste into
     * @param copyIndex The index in copyFromData to copying from
     * @param pasteIndex The index in pasteToData to paste into
     **/
    function paste32Bytes(
        bytes memory copyFromData,
        bytes memory pasteToData,
        uint256 copyIndex,
        uint256 pasteIndex
    ) internal pure {
        assembly {
            mstore(add(pasteToData, pasteIndex), mload(add(copyFromData, copyIndex)))
        }
    }

    ///////// DEPOSIT ID /////////

    function packAddressAndStem(address _address, int96 stem) internal pure returns (uint256) {
        return (uint256(uint160(_address)) << 96) | uint96(stem);
    }

    function unpackAddressAndStem(uint256 data) internal pure returns (address, int96) {
        return (address(uint160(data >> 96)), int96(int256(data)));
    }

    /////// CLIPBOARD ///////

    /**
     * @notice Paste bytes using clipboard parameters.
     * @dev Reverts if `getCopyReturnIndex` returns an
     * invalid index (i.e < `copyFromDataSet.length`)
     */
    function pasteBytesClipboard(
        bytes32 returnPasteParam, // Copy/paste instructions.
        bytes[] memory copyFromDataSet, // data to copy from.
        bytes memory pasteToData // Paste destination.
    ) internal pure {
        (uint256 copyReturnIndex, uint256 copyByteIndex, uint256 pasteByteIndex) = decode(
            returnPasteParam
        );
        bytes memory copyFromData = copyFromDataSet[copyReturnIndex];

        // Verify that the copyFromData and pasteToData are valid.
        verifyCopyByteIndex(copyByteIndex, copyFromData);
        verifyPasteByteIndex(pasteByteIndex, pasteToData);

        // Copy 32 bytes from copyFromData at copyByteIndex and
        // paste into pasteToData at pasteByteIndex.
        paste32Bytes(copyFromData, pasteToData, copyByteIndex, pasteByteIndex);
    }

    /////// TRACTOR ///////

    /**
     * @notice Paste bytes using tractor parameters.
     *
     *  OperatorPasteInstrs: Copy bytes32 from operator data into calldata
     *       [ Padding     | copyByteIndex | pasteCallIndex | pasteByteIndex ]
     *       [ 2 bytes     | 10 bytes      | 10 bytes       | 10 bytes       ]
     */
    function pasteBytesTractor(
        bytes32 operatorPasteInstr,
        bytes memory copyFromData,
        bytes memory pasteToData
    ) internal view {
        // Decode operatorPasteInstr.
        (uint80 copyByteIndex, , uint80 pasteByteIndex) = decode(operatorPasteInstr);

        // if copyByteIndex matches the publisher or operator index,
        // replace data with the publisher/operator address.
        if (copyByteIndex == C.PUBLISHER_COPY_INDEX) {
            copyFromData = abi.encodePacked(
                uint256(uint160(address(LibTractor._tractorStorage().activePublisher)))
            );
            copyByteIndex = C.SLOT_SIZE;
        } else if (copyByteIndex == C.OPERATOR_COPY_INDEX) {
            copyFromData = abi.encodePacked(uint256(uint160(msg.sender)));
            copyByteIndex = C.SLOT_SIZE;
        }

        // Verify that the copyFromData and pasteToData are valid.
        verifyCopyByteIndex(copyByteIndex, copyFromData);
        verifyPasteByteIndex(pasteByteIndex, pasteToData);

        // Copy 32 bytes from copyFromData at copyByteIndex and
        // paste into pasteToData at pasteByteIndex.
        paste32Bytes(copyFromData, pasteToData, copyByteIndex, pasteByteIndex);
    }

    /////// BYTES32 ENCODED INDICES ///////

    /**
     * @notice Verifies that the byte index of the copy data is within bounds.
     */
    function verifyCopyByteIndex(uint256 copyByteIndex, bytes memory copyFromData) internal pure {
        require(C.SLOT_SIZE <= copyByteIndex, "LibBytes: copyByteIndex too small");
        require(copyByteIndex <= copyFromData.length, "LibBytes: copyByteIndex too large");
    }

    /**
     * @notice Verifies that the paste index of the copy data is within bounds.
     */
    function verifyPasteByteIndex(uint256 pasteByteIndex, bytes memory pasteToData) internal pure {
        require(C.SLOT_SIZE <= pasteByteIndex, "LibBytes: pasteByteIndex too small");
        require(pasteByteIndex <= pasteToData.length, "LibBytes: pasteByteIndex too large");
    }

    /**
     * @notice Encodes an tractor blueprint operator paste or
     * a clipboard paste param instruction.
     * @dev If returnPasteParam, values are (copyReturnIndex, copyByteIndex, pasteByteIndex).
     * @dev If operatorPasteInstr, values are (copyByteIndex, pasteCallIndex, pasteByteIndex).
     */
    function encode(
        uint80 _index0,
        uint80 _index1,
        uint80 _index2
    ) internal pure returns (bytes32) {
        return toBytes32(abi.encodePacked(bytes2(0), _index0, _index1, _index2), 0);
    }

    /**
     * @notice Decodes a copyPasteInstruction into the
     * copy return index, copy byte index, and paste byte index.
     * @dev If returnPasteParam, the return is (copyReturnIndex, copyByteIndex, pasteByteIndex).
     * @dev If operatorPasteInstr, the return is (copyByteIndex, pasteCallIndex, pasteByteIndex).
     */
    function decode(bytes32 indices) internal pure returns (uint80, uint80, uint80) {
        return (getIndex0(indices), getIndex1(indices), getIndex2(indices));
    }

    /**
     * @notice Returns the index at position 0 in a bytes32 encoded set of indices. Either the copy return index or the paste call index.
     * @dev Used in `pasteBytesClipboard` to choose which return parameter to copy from.
     * @dev returnPasteParam.copyReturnIndex OR operatorPasteInstr.copyByteIndex.
     */
    function getIndex0(bytes32 indices) internal pure returns (uint80) {
        return uint80(bytes10(indices << 16));
    }

    /**
     * @notice Returns the index at position 1 in a bytes32 encoded set of indices. The copy byte index.
     * @dev Used to determine what byte index to start copying 32 bytes from.
     * @dev returnPasteParam.copyByteIndex OR operatorPasteInstr.pasteCallIndex.
     */
    function getIndex1(bytes32 indices) internal pure returns (uint80) {
        return uint80(bytes10(indices << 96));
    }

    /**
     * @notice Returns the index at position 2 in a bytes32 encoded set of indices. The paste byte index.
     * @dev Used to determine what byte index to paste in data at.
     * @dev returnPasteParam.pasteByteIndex OR operatorPasteInstr.pasteByteIndex.
     */
    function getIndex2(bytes32 indices) internal pure returns (uint80) {
        return uint80(bytes10(indices << 176));
    }
}

contracts/libraries/LibTractor.sol.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

/**
 * @title Lib Tractor
 * @author funderbrker
 **/
library LibTractor {
    enum CounterUpdateType {
        INCREASE,
        DECREASE
    }

    bytes32 private constant TRACTOR_HASHED_NAME = keccak256(bytes("Tractor"));
    bytes32 private constant EIP712_TYPE_HASH =
        keccak256(
            bytes(
                "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
            )
        );
    bytes32 public constant BLUEPRINT_TYPE_HASH =
        keccak256(
            bytes(
                "Blueprint(address publisher,bytes data,bytes32[] operatorPasteInstrs,uint256 maxNonce,uint256 startTime,uint256 endTime)"
            )
        );

    event TractorVersionSet(string version);

    struct TractorStorage {
        // Number of times the blueprint has been run.
        mapping(bytes32 => uint256) blueprintNonce;
        // Publisher Address => counter id => counter value.
        mapping(address => mapping(bytes32 => uint256)) blueprintCounters;
        // Publisher of current operations. Set to address(1) when no active publisher.
        address payable activePublisher;
        // Version of Tractor. Only Blueprints using current Version can run.
        string version;
    }

    // Blueprint stores blueprint related values
    struct Blueprint {
        address publisher;
        bytes data;
        bytes32[] operatorPasteInstrs;
        uint256 maxNonce;
        uint256 startTime;
        uint256 endTime;
    }

    /**
     * @notice Stores blueprint, hash, and signature, which enables verification.
     */
    struct Requisition {
        Blueprint blueprint;
        bytes32 blueprintHash; // including this is not strictly necessary, but helps avoid hashing more than once on chain
        bytes signature;
    }

    /**
     * @notice Get tractor storage from storage.
     * @return ts Storage object containing tractor data
     */
    function _tractorStorage() internal pure returns (TractorStorage storage ts) {
        // keccak256("diamond.storage.tractor") == 0x7efbaaac9214ca1879e26b4df38e29a72561affb741bba775ce66d5bb6a82a07
        assembly {
            ts.slot := 0x7efbaaac9214ca1879e26b4df38e29a72561affb741bba775ce66d5bb6a82a07
        }
    }

    /**
     * @notice Set the tractor hashed version.
     */
    function _setVersion(string memory version) internal {
        _tractorStorage().version = version;
        emit TractorVersionSet(version);
    }

    /**
     * @notice Increment the blueprint nonce by 1.
     * @param blueprintHash blueprint hash
     */
    function _incrementBlueprintNonce(bytes32 blueprintHash) internal {
        _tractorStorage().blueprintNonce[blueprintHash]++;
    }

    /**
     * @notice Cancel blueprint.
     * @dev set blueprintNonce to type(uint256).max
     * @param blueprintHash blueprint hash
     */
    function _cancelBlueprint(bytes32 blueprintHash) internal {
        _tractorStorage().blueprintNonce[blueprintHash] = type(uint256).max;
    }

    /**
     * @notice Set blueprint publisher address.
     * @param publisher blueprint publisher address
     */
    function _setPublisher(address payable publisher) internal {
        TractorStorage storage ts = _tractorStorage();
        require(
            uint160(bytes20(address(ts.activePublisher))) <= 1,
            "LibTractor: publisher already set"
        );
        ts.activePublisher = publisher;
    }

    /**
     * @notice Reset blueprint publisher address.
     */
    function _resetPublisher() internal {
        _tractorStorage().activePublisher = payable(address(1));
    }

    /** @notice Return current activePublisher address.
     * @return publisher current activePublisher address
     */
    function _getActivePublisher() internal view returns (address payable) {
        return _tractorStorage().activePublisher;
    }

    /** @notice Return current activePublisher address or msg.sender if no active blueprint.
     * @return user to take actions on behalf of
     */
    function _user() internal view returns (address payable user) {
        user = _getActivePublisher();
        if (uint160(bytes20(address(user))) <= 1) {
            user = payable(msg.sender);
        }
    }

    /**
     * @notice Get blueprint nonce.
     * @param blueprintHash blueprint hash
     * @return nonce current blueprint nonce
     */
    function _getBlueprintNonce(bytes32 blueprintHash) internal view returns (uint256) {
        return _tractorStorage().blueprintNonce[blueprintHash];
    }

    /**
     * @notice Calculates blueprint hash.
     * @dev https://eips.ethereum.org/EIPS/eip-712
     * @dev  https://github.com/BeanstalkFarms/Beanstalk/pull/727#discussion_r1577293450
     * @param blueprint blueprint object
     * @return hash calculated Blueprint hash
     */
    function _getBlueprintHash(Blueprint calldata blueprint) internal view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        BLUEPRINT_TYPE_HASH,
                        blueprint.publisher,
                        keccak256(blueprint.data),
                        keccak256(abi.encodePacked(blueprint.operatorPasteInstrs)),
                        blueprint.maxNonce,
                        blueprint.startTime,
                        blueprint.endTime
                    )
                )
            );
    }

    /**
     * @notice Hashes in an EIP712 compliant way.
     * @dev Returns an Ethereum Signed Typed Data, created from a
     * `domainSeparator` and a `structHash`. This produces hash corresponding
     * to the one signed with the
     * https://eips.ethereum.org/EIPS/eip-712[`eth_signTypedData`]
     * JSON-RPC method as part of EIP-712.
     *
     * Sourced from OpenZeppelin 0.8 ECDSA lib.
     */
    function _hashTypedDataV4(bytes32 structHash) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), structHash));
    }

    /**
     * @notice Returns the domain separator for the current chain.
     */
    function _domainSeparatorV4() internal view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    EIP712_TYPE_HASH,
                    TRACTOR_HASHED_NAME,
                    keccak256(bytes(_tractorStorage().version)),
                    block.chainid,
                    address(this)
                )
            );
    }
}

contracts/libraries/Oracle/LibChainlinkO.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {IChainlinkAggregator} from "contracts/interfaces/chainlink/IChainlinkAggregator.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";

/**
 * @title Chainlink Oracle Library
 * @notice Contains functionalty to fetch prices from Chainlink price feeds.
 * @dev currently supports:
 * - ETH/USD price feed
 **/
library LibChainlinkOracle {
    using LibRedundantMath256 for uint256;

    uint256 constant PRECISION = 1e6; // use 6 decimal precision.

    // timeout for Oracles with a 1 hour heartbeat.
    uint256 constant FOUR_HOUR_TIMEOUT = 14400;
    // timeout for Oracles with a 1 day heartbeat.
    uint256 constant FOUR_DAY_TIMEOUT = 345600;

    struct TwapVariables {
        uint256 cumulativePrice;
        uint256 endTimestamp;
        uint256 lastTimestamp;
    }

    /**
     * @dev Returns the TOKEN1/TOKEN2, or TOKEN2/TOKEN1 price with the option of using a TWA lookback.
     * Use `lookback = 0` for the instantaneous price. `lookback > 0` for a TWAP.
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if `priceAggregatorAddress` is broken or frozen.
     **/
    function getTokenPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback,
        bool isMillion
    ) internal view returns (uint256 price) {
        return
            lookback > 0
                ? getTwap(priceAggregatorAddress, maxTimeout, tokenDecimals, lookback, isMillion)
                : getPrice(priceAggregatorAddress, maxTimeout, tokenDecimals, isMillion);
    }

    function getTokenPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback
    ) internal view returns (uint256 price) {
        return getTokenPrice(priceAggregatorAddress, maxTimeout, tokenDecimals, lookback, false);
    }

    /**
     * @dev Returns the price of a given `priceAggregator`
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price
     * where TOKEN1 is the numerator asset and TOKEN2 is the asset the oracle is denominated in.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if Chainlink's price feed is broken or frozen.
     **/
    function getPrice(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        bool isMillion
    ) internal view returns (uint256 price) {
        IChainlinkAggregator priceAggregator = IChainlinkAggregator(priceAggregatorAddress);
        // First, try to get current decimal precision:
        uint8 decimals;
        try priceAggregator.decimals() returns (uint8 _decimals) {
            // If call to Chainlink succeeds, record the current decimal precision
            decimals = _decimals;
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }

        // Secondly, try to get latest price data:
        try priceAggregator.latestRoundData() returns (
            uint80 roundId,
            int256 answer,
            uint256 /* startedAt */,
            uint256 timestamp,
            uint80 /* answeredInRound */
        ) {
            // Check for an invalid roundId that is 0
            if (roundId == 0) return 0;
            if (checkForInvalidTimestampOrAnswer(timestamp, answer, block.timestamp, maxTimeout)) {
                return 0;
            }

            // if token decimals is greater than 0, return the TOKEN2/TOKEN1 price instead (i.e invert the price).
            if (tokenDecimals > 0) {
                // if `isMillion` is set, return `MillionTOKEN2/TOKEN1` Price instead
                // (i.e, the amount of TOKEN1 equal to a million of TOKEN2)
                if (isMillion) tokenDecimals = tokenDecimals + 6;
                price = uint256(10 ** (tokenDecimals + decimals)).div(uint256(answer));
            } else {
                // Adjust to 6 decimal precision.
                price = uint256(answer).mul(PRECISION).div(10 ** decimals);
            }
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }
    }

    /**
     * @dev Returns the TWAP price from the Chainlink Oracle over the past `lookback` seconds.
     * Use `tokenDecimals = 0` for TOKEN1/TOKEN2 price. `tokenDecimals > 0` for TOKEN2/TOKEN1 price.
     * Return value has 6 decimal precision if using TOKEN1/TOKEN2, and `tokenDecimals` if using TOKEN2/TOKEN1.
     * Returns 0 if Chainlink's price feed is broken or frozen.
     **/
    function getTwap(
        address priceAggregatorAddress,
        uint256 maxTimeout,
        uint256 tokenDecimals,
        uint256 lookback,
        bool isMillion
    ) internal view returns (uint256 price) {
        // First, try to get current decimal precision:
        uint8 decimals;
        try IChainlinkAggregator(priceAggregatorAddress).decimals() returns (uint8 _decimals) {
            // If call to Chainlink succeeds, record the current decimal precision
            decimals = _decimals;
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }

        // Secondly, try to get latest price data:
        try IChainlinkAggregator(priceAggregatorAddress).latestRoundData() returns (
            uint80 roundId,
            int256 answer,
            uint256 /* startedAt */,
            uint256 timestamp,
            uint80 /* answeredInRound */
        ) {
            // Check for an invalid roundId that is 0
            if (roundId == 0) return 0;
            if (checkForInvalidTimestampOrAnswer(timestamp, answer, block.timestamp, maxTimeout)) {
                return 0;
            }

            TwapVariables memory t;

            t.endTimestamp = block.timestamp.sub(lookback);

            if (isMillion) {
                // if `isMillion` flag is enabled,
                tokenDecimals = tokenDecimals + 6;
            }
            // Check if last round was more than `lookback` ago.
            if (timestamp <= t.endTimestamp) {
                if (tokenDecimals > 0) {
                    return uint256(10 ** (tokenDecimals + decimals)).div(uint256(answer));
                } else {
                    // Adjust to 6 decimal precision.
                    return uint256(answer).mul(PRECISION).div(10 ** decimals);
                }
            } else {
                t.lastTimestamp = block.timestamp;
                // Loop through previous rounds and compute cumulative sum until
                // a round at least `lookback` seconds ago is reached.
                while (timestamp > t.endTimestamp) {
                    // if token decimals is greater than 0, return the TOKEN2/TOKEN1 price instead (i.e invert the price).
                    if (tokenDecimals > 0) {
                        answer = int256((10 ** (tokenDecimals + decimals)) / (uint256(answer)));
                    }
                    t.cumulativePrice = t.cumulativePrice.add(
                        uint256(answer).mul(t.lastTimestamp.sub(timestamp))
                    );
                    roundId -= 1;
                    t.lastTimestamp = timestamp;
                    (answer, timestamp) = getRoundData(
                        IChainlinkAggregator(priceAggregatorAddress),
                        roundId
                    );
                    if (
                        checkForInvalidTimestampOrAnswer(
                            timestamp,
                            answer,
                            t.lastTimestamp,
                            maxTimeout
                        )
                    ) {
                        return 0;
                    }
                }
                if (tokenDecimals > 0) {
                    answer = int256((10 ** (tokenDecimals + decimals)) / (uint256(answer)));
                }
                t.cumulativePrice = t.cumulativePrice.add(
                    uint256(answer).mul(t.lastTimestamp.sub(t.endTimestamp))
                );
                if (tokenDecimals > 0) {
                    price = t.cumulativePrice.div(lookback);
                } else {
                    price = t.cumulativePrice.mul(PRECISION).div(10 ** decimals).div(lookback);
                }
            }
        } catch {
            // If call to Chainlink aggregator reverts, return a price of 0 indicating failure
            return 0;
        }
    }

    function getRoundData(
        IChainlinkAggregator priceAggregator,
        uint80 roundId
    ) private view returns (int256, uint256) {
        try priceAggregator.getRoundData(roundId) returns (
            uint80 /* roundId */,
            int256 _answer,
            uint256 /* startedAt */,
            uint256 _timestamp,
            uint80 /* answeredInRound */
        ) {
            return (_answer, _timestamp);
        } catch {
            return (-1, 0);
        }
    }

    function checkForInvalidTimestampOrAnswer(
        uint256 timestamp,
        int256 answer,
        uint256 currentTimestamp,
        uint256 maxTimeout
    ) private pure returns (bool) {
        // Check for an invalid timeStamp that is 0, or in the future
        if (timestamp == 0 || timestamp > currentTimestamp) return true;
        // Check if Chainlink's price feed has timed out
        if (currentTimestamp.sub(timestamp) > maxTimeout) return true;
        // Check for non-positive price
        if (answer <= 0) return true;

        return false;
    }
}

