                            return 0.6128602937515535e18; // 90,000,000, 0.21
                        } else {
                            return 0.6363596297698088e18; // 90,000,000, 0.19
                        }
                    } else if (recapPercentPaid > 0.14e6) {
                        if (recapPercentPaid > 0.15e6) {
