                        } else {
                            return 0.6891914824733962e18; // 90,000,000, 0.15
                        }
                    } else if (recapPercentPaid > 0.12e6) {
                        if (recapPercentPaid > 0.13e6) {
                            return 0.7037939098015373e18; // 90,000,000, 0.14
                        } else {
                            return 0.719026126689054e18; // 90,000,000, 0.13
                        }
                    } else {
