// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

/**
 * @title LibConvertData
 * @author LeoFib
 */
library LibConvertData {
    // In order to preserve backwards compatibility, make sure new kinds are added at the end of the enum.
    enum ConvertKind {
        DEPRECATED_0, // BEANS_TO_CURVE_LP
        DEPRECATED_1, // CURVE_LP_TO_BEANS
        UNRIPE_BEANS_TO_UNRIPE_LP,
        UNRIPE_LP_TO_UNRIPE_BEANS,
        LAMBDA_LAMBDA,
        BEANS_TO_WELL_LP,
        WELL_LP_TO_BEANS,
        UNRIPE_TO_RIPE,
        ANTI_LAMBDA_LAMBDA
    }

    /// @notice Decoder for the Convert Enum
    function convertKind(bytes memory self) internal pure returns (ConvertKind) {
        return abi.decode(self, (ConvertKind));
    }

    /// @notice Decoder for the addLPInBeans Convert
    function basicConvert(
        bytes memory self
    ) internal pure returns (uint256 amountIn, uint256 minAmontOut) {
        (, amountIn, minAmontOut) = abi.decode(self, (ConvertKind, uint256, uint256));
    }

    /// @notice Decoder for the addLPInBeans Convert
    function convertWithAddress(
        bytes memory self
    ) internal pure returns (uint256 amountIn, uint256 minAmontOut, address token) {
        (, amountIn, minAmontOut, token) = abi.decode(
            self,
            (ConvertKind, uint256, uint256, address)
        );
    }

    /// @notice Decoder for the lambdaConvert
    function lambdaConvert(
        bytes memory self
    ) internal pure returns (uint256 amount, address token) {
        (, amount, token) = abi.decode(self, (ConvertKind, uint256, address));
    }

    /// @notice Decoder for the antiLambdaConvert
    /// @dev contains an additional address parameter for the account to update the deposit
    /// and a bool to indicate whether to decrease the bdv
    function antiLambdaConvert(
        bytes memory self
    ) internal pure returns (uint256 amount, address token, address account, bool decreaseBDV) {
        (, amount, token, account) = abi.decode(self, (ConvertKind, uint256, address, address));
        decreaseBDV = true;
    }
}

contracts/libraries/Convert/LibLambdaCon.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {LibConvertData} from "./LibConvertData.sol";

/**
 * @title LibLambdaConvert
 * @author Publius, deadmanwalking
 */
library LibLambdaConvert {
    using LibConvertData for bytes;

    /**
     * @notice This function returns the full input for use in lambda convert
     * In lambda convert, the account converts from and to the same token.
     */
    function convert(
        bytes memory convertData
    )
        internal
        pure
        returns (address tokenOut, address tokenIn, uint256 amountOut, uint256 amountIn)
    {
        (amountIn, tokenIn) = convertData.lambdaConvert();
        tokenOut = tokenIn;
        amountOut = amountIn;
    }

    /**
     * @notice This function returns the full input for use in anti-lamda convert
     * In anti lamda convert, any user can convert on behalf of an account
     * to update a deposit's bdv.
     * This is why the additional 'account' parameter is returned.
     */
    function antiConvert(
        bytes memory convertData
    )
        internal
        pure
        returns (
            address tokenOut,
            address tokenIn,
            uint256 amountOut,
            uint256 amountIn,
            address account,
            bool decreaseBDV
        )
    {
        (amountIn, tokenIn, account, decreaseBDV) = convertData.antiLambdaConvert();
        tokenOut = tokenIn;
        amountOut = amountIn;
    }
}

contracts/libraries/Convert/LibPipelineC.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {LibConvert} from "./LibConvert.sol";
import {AdvancedPipeCall} from "contracts/interfaces/IPipeline.sol";
import {LibWell} from "../Well/LibWell.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibDeltaB} from "contracts/libraries/Oracle/LibDeltaB.sol";
import {IPipeline, PipeCall} from "contracts/interfaces/IPipeline.sol";
import {LibConvertData} from "contracts/libraries/Convert/LibConvertData.sol";
import {LibTokenSilo} from "contracts/libraries/Silo/LibTokenSilo.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";

/**
 * @title LibPipelineConvert
 * @author pizzaman1337, Brean
 */
library LibPipelineConvert {
    using LibConvertData for bytes;
    /**
     * @notice contains data for a convert that uses Pipeline.
     */
    struct PipelineConvertData {
        uint256 grownStalk;
        LibConvert.DeltaBStorage deltaB;
        uint256 inputAmount;
        uint256 overallConvertCapacity;
        uint256 stalkPenaltyBdv;
        address user;
        uint256 newBdv;
        uint256[] initialLpSupply;
    }

    function executePipelineConvert(
        address inputToken,
        address outputToken,
        uint256 fromAmount,
        uint256 fromBdv,
        uint256 initialGrownStalk,
        AdvancedPipeCall[] memory advancedPipeCalls
    ) external returns (uint256 toAmount, uint256 newGrownStalk, uint256 newBdv) {
        PipelineConvertData memory pipeData = LibPipelineConvert.populatePipelineConvertData(
            inputToken,
            outputToken
        );

        // Store the capped overall deltaB, this limits the overall convert power for the block
        pipeData.overallConvertCapacity = LibConvert.abs(LibDeltaB.overallCappedDeltaB());

        IERC20(inputToken).transfer(C.PIPELINE, fromAmount);
        IPipeline(C.PIPELINE).advancedPipe(advancedPipeCalls);

        // user MUST leave final assets in pipeline, allowing us to verify that the farm has been called successfully.
        // this also let's us know how many assets to attempt to pull out of the final type
        toAmount = transferTokensFromPipeline(outputToken);

        newBdv = LibTokenSilo.beanDenominatedValue(outputToken, toAmount);

        // Calculate stalk penalty using start/finish deltaB of pools, and the capped deltaB is
        // passed in to setup max convert power.
        pipeData.stalkPenaltyBdv = prepareStalkPenaltyCalculation(
            inputToken,
            outputToken,
            pipeData.deltaB,
            pipeData.overallConvertCapacity,
            newBdv,
            pipeData.initialLpSupply
        );

        // scale initial grown stalk proportionally to the bdv lost (if any)
        if (newBdv < fromBdv) {
            initialGrownStalk = (initialGrownStalk * newBdv) / fromBdv;
        }

        // Update grownStalk amount with penalty applied
        newGrownStalk = (initialGrownStalk * (newBdv - pipeData.stalkPenaltyBdv)) / newBdv;
    }

    /**
     * @notice Calculates the stalk penalty for a convert. Updates convert capacity used.
     */
    function prepareStalkPenaltyCalculation(
        address inputToken,
        address outputToken,
        LibConvert.DeltaBStorage memory dbs,
        uint256 overallConvertCapacity,
        uint256 fromBdv,
        uint256[] memory initialLpSupply
    ) public returns (uint256) {
        dbs.afterOverallDeltaB = LibDeltaB.scaledOverallCurrentDeltaB(initialLpSupply);

        // modify afterInputTokenDeltaB and afterOutputTokenDeltaB to scale using before/after LP amounts
        if (LibWell.isWell(inputToken)) {
            uint256 i = LibWhitelistedTokens.getIndexFromWhitelistedWellLpTokens(inputToken);
            dbs.afterInputTokenDeltaB = LibDeltaB.scaledDeltaB(
                initialLpSupply[i],
                IERC20(inputToken).totalSupply(),
                LibDeltaB.getCurrentDeltaB(inputToken)
            );
        }

        if (LibWell.isWell(outputToken)) {
            uint256 i = LibWhitelistedTokens.getIndexFromWhitelistedWellLpTokens(outputToken);
            dbs.afterOutputTokenDeltaB = LibDeltaB.scaledDeltaB(
                initialLpSupply[i],
                IERC20(outputToken).totalSupply(),
                LibDeltaB.getCurrentDeltaB(outputToken)
            );
        }

        return
            LibConvert.applyStalkPenalty(
                dbs,
                fromBdv,
                overallConvertCapacity,
                inputToken,
                outputToken
            );
    }

    /**
     * @notice Determines input token amount left in pipeline and returns to Beanstalk
     * @param tokenOut The token to pull out of pipeline
     */
    function transferTokensFromPipeline(address tokenOut) internal returns (uint256 amountOut) {
        amountOut = IERC20(tokenOut).balanceOf(C.PIPELINE);
        require(amountOut > 0, "Convert: No output tokens left in pipeline");

        PipeCall memory p;
        p.target = address(tokenOut);
        p.data = abi.encodeWithSelector(IERC20.transfer.selector, address(this), amountOut);
        C.pipeline().pipe(p);
    }

    function populatePipelineConvertData(
        address fromToken,
        address toToken
    ) internal view returns (PipelineConvertData memory pipeData) {
        pipeData.deltaB.beforeOverallDeltaB = LibDeltaB.overallCurrentDeltaB();
        pipeData.deltaB.beforeInputTokenDeltaB = LibDeltaB.getCurrentDeltaB(fromToken);
        pipeData.deltaB.beforeOutputTokenDeltaB = LibDeltaB.getCurrentDeltaB(toToken);
        pipeData.initialLpSupply = LibDeltaB.getLpSupply();
    }

    /**
     * @notice Determines the convert state and populates pipeline data if necessary
     */
    function getConvertState(
        bytes calldata convertData
    ) public view returns (PipelineConvertData memory pipeData) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        LibConvertData.ConvertKind kind = convertData.convertKind();
        address toToken;
        address fromToken;
        if (
            kind == LibConvertData.ConvertKind.BEANS_TO_WELL_LP ||
            kind == LibConvertData.ConvertKind.WELL_LP_TO_BEANS
        ) {
            if (kind == LibConvertData.ConvertKind.BEANS_TO_WELL_LP) {
                (, , toToken) = convertData.convertWithAddress();
                fromToken = s.sys.tokens.bean;
                require(LibWell.isWell(toToken), "Convert: Invalid Well");
            } else {
                (, , fromToken) = convertData.convertWithAddress();
                toToken = s.sys.tokens.bean;
                require(LibWell.isWell(fromToken), "Convert: Invalid Well");
            }

            pipeData = populatePipelineConvertData(fromToken, toToken);
        }
    }

    /**
     * @notice reverts if the convert would be penalized.
     * @dev used in {ConvertFacet.convert}
     */
    function checkForValidConvertAndUpdateConvertCapacity(
        PipelineConvertData memory pipeData,
        bytes calldata convertData,
        address fromToken,
        address toToken,
        uint256 fromBdv
    ) public {
        LibConvertData.ConvertKind kind = convertData.convertKind();
        if (
            kind == LibConvertData.ConvertKind.BEANS_TO_WELL_LP ||
            kind == LibConvertData.ConvertKind.WELL_LP_TO_BEANS
        ) {
            pipeData.overallConvertCapacity = LibConvert.abs(LibDeltaB.overallCappedDeltaB());

            pipeData.stalkPenaltyBdv = prepareStalkPenaltyCalculation(
                fromToken,
                toToken,
                pipeData.deltaB,
                pipeData.overallConvertCapacity,
                fromBdv,
                pipeData.initialLpSupply
            );

            require(pipeData.stalkPenaltyBdv == 0, "Convert: Non-zero Stalk Penalty");
        }
    }
}

contracts/libraries/Convert/LibUnripeCon.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {IBean} from "contracts/interfaces/IBean.sol";
import {LibWellConvert} from "./LibWellConvert.sol";
import {LibUnripe} from "../LibUnripe.sol";
import {LibConvertData} from "./LibConvertData.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibBarnRaise} from "contracts/libraries/LibBarnRaise.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";

/**
 * @title LibUnripeConvert
 * @author Publius
 */
library LibUnripeConvert {
    using LibConvertData for bytes;
    using LibRedundantMath256 for uint256;

    function convertLPToBeans(
        bytes memory convertData
    ) internal returns (address tokenOut, address tokenIn, uint256 amountOut, uint256 amountIn) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        tokenOut = s.sys.tokens.urBean;
        tokenIn = s.sys.tokens.urLp;
        (uint256 lp, uint256 minBeans) = convertData.basicConvert();
        uint256 minAmountOut = LibUnripe
            .unripeToUnderlying(tokenOut, minBeans, IBean(s.sys.tokens.urBean).totalSupply())
            .mul(LibUnripe.percentLPRecapped())
            .div(LibUnripe.percentBeansRecapped());
        (uint256 outUnderlyingAmount, uint256 inUnderlyingAmount) = LibWellConvert
            ._wellRemoveLiquidityTowardsPeg(
                LibUnripe.unripeToUnderlying(tokenIn, lp, IBean(s.sys.tokens.urLp).totalSupply()),
                minAmountOut,
                LibBarnRaise.getBarnRaiseWell()
            );

        amountIn = LibUnripe.underlyingToUnripe(tokenIn, inUnderlyingAmount);
        LibUnripe.removeUnderlying(tokenIn, inUnderlyingAmount);
        IBean(tokenIn).burn(amountIn);

        amountOut = LibUnripe
            .underlyingToUnripe(tokenOut, outUnderlyingAmount)
            .mul(LibUnripe.percentBeansRecapped())
            .div(LibUnripe.percentLPRecapped());
        LibUnripe.addUnderlying(tokenOut, outUnderlyingAmount);
        IBean(tokenOut).mint(address(this), amountOut);
    }

    function convertBeansToLP(
        bytes memory convertData
    ) internal returns (address tokenOut, address tokenIn, uint256 amountOut, uint256 amountIn) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        tokenIn = s.sys.tokens.urBean;
        tokenOut = s.sys.tokens.urLp;
        (uint256 beans, uint256 minLP) = convertData.basicConvert();
        uint256 minAmountOut = LibUnripe
            .unripeToUnderlying(tokenOut, minLP, IBean(s.sys.tokens.urLp).totalSupply())
            .mul(LibUnripe.percentBeansRecapped())
            .div(LibUnripe.percentLPRecapped());
        (uint256 outUnderlyingAmount, uint256 inUnderlyingAmount) = LibWellConvert
            ._wellAddLiquidityTowardsPeg(
                LibUnripe.unripeToUnderlying(
                    tokenIn,
                    beans,
                    IBean(s.sys.tokens.urBean).totalSupply()
                ),
                minAmountOut,
                LibBarnRaise.getBarnRaiseWell()
            );

        amountIn = LibUnripe.underlyingToUnripe(tokenIn, inUnderlyingAmount);
        LibUnripe.removeUnderlying(tokenIn, inUnderlyingAmount);
        IBean(tokenIn).burn(amountIn);

        amountOut = LibUnripe
            .underlyingToUnripe(tokenOut, outUnderlyingAmount)
            .mul(LibUnripe.percentLPRecapped())
            .div(LibUnripe.percentBeansRecapped());
        LibUnripe.addUnderlying(tokenOut, outUnderlyingAmount);
        IBean(tokenOut).mint(address(this), amountOut);
    }

    function beansToPeg() internal view returns (uint256 beans) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 underlyingBeans = LibWellConvert.beansToPeg(LibBarnRaise.getBarnRaiseWell());
        beans = LibUnripe.underlyingToUnripe(s.sys.tokens.urBean, underlyingBeans);
    }

    function lpToPeg() internal view returns (uint256 lp) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 underlyingLP = LibWellConvert.lpToPeg(LibBarnRaise.getBarnRaiseWell());
        lp = LibUnripe.underlyingToUnripe(s.sys.tokens.urLp, underlyingLP);
    }

    function getLPAmountOut(uint256 amountIn) internal view returns (uint256 lp) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 beans = LibUnripe.unripeToUnderlying(
            s.sys.tokens.urBean,
            amountIn,
            IBean(s.sys.tokens.urBean).totalSupply()
        );
        lp = LibWellConvert.getLPAmountOut(LibBarnRaise.getBarnRaiseWell(), beans);
        lp = LibUnripe
            .underlyingToUnripe(s.sys.tokens.urLp, lp)
            .mul(LibUnripe.percentLPRecapped())
            .div(LibUnripe.percentBeansRecapped());
    }

    function getBeanAmountOut(uint256 amountIn) internal view returns (uint256 bean) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 lp = LibUnripe.unripeToUnderlying(
            s.sys.tokens.urLp,
            amountIn,
            IBean(s.sys.tokens.urLp).totalSupply()
        );
        bean = LibWellConvert.getBeanAmountOut(LibBarnRaise.getBarnRaiseWell(), lp);
        bean = LibUnripe
            .underlyingToUnripe(s.sys.tokens.urBean, bean)
            .mul(LibUnripe.percentBeansRecapped())
            .div(LibUnripe.percentLPRecapped());
    }
}

contracts/libraries/Convert/LibWellConve.content:
/*
 SPDX-License-Identifier: MIT
*/

pragma solidity ^0.8.20;

import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibConvertData} from "contracts/libraries/Convert/LibConvertData.sol";
import {LibWell} from "contracts/libraries/Well/LibWell.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Call, IWell} from "contracts/interfaces/basin/IWell.sol";
import {IBeanstalkWellFunction} from "contracts/interfaces/basin/IBeanstalkWellFunction.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";
import {BeanstalkERC20} from "contracts/tokens/ERC20/BeanstalkERC20.sol";

/**
 * @title Well Convert Library
 * @notice Contains Functions to convert from/to Well LP tokens to/from Beans
 * in the direction of the Peg.
 **/
library LibWellConvert {
    using LibRedundantMath256 for uint256;
    using LibConvertData for bytes;

    /**
     * @dev Calculates the maximum amount of Beans that can be
     * convert to the LP Token of a given `well` while maintaining a delta B >= 0.
     */
    function beansToPeg(address well) internal view returns (uint256 beans) {
        (beans, ) = _beansToPeg(well);
    }

    /**
     * An internal version of `beansToPeg` that always returns the
     * index of the Bean token in a given `well`.
     */
    function _beansToPeg(address well) internal view returns (uint256 beans, uint256 beanIndex) {
        IERC20[] memory tokens = IWell(well).tokens();
        uint256[] memory reserves = IWell(well).getReserves();
        Call memory wellFunction = IWell(well).wellFunction();
        uint256[] memory ratios;
        bool success;
        (ratios, beanIndex, success) = LibWell.getRatiosAndBeanIndex(tokens);
        // If the USD Oracle oracle call fails, the convert should not be allowed.
        require(success, "Convert: USD Oracle failed");

        uint256 beansAtPeg = IBeanstalkWellFunction(wellFunction.target)
            .calcReserveAtRatioLiquidity(reserves, beanIndex, ratios, wellFunction.data);

        if (beansAtPeg <= reserves[beanIndex]) return (0, beanIndex);
        beans = beansAtPeg - reserves[beanIndex];
    }

    /**
     * @dev Calculates the maximum amount of LP Tokens of a given `well` that can be
     * converted to Beans while maintaining a delta B <= 0.
     */
    function lpToPeg(address well) internal view returns (uint256 lp) {
        IERC20[] memory tokens = IWell(well).tokens();
        uint256[] memory reserves = IWell(well).getReserves();
        Call memory wellFunction = IWell(well).wellFunction();
        (uint256[] memory ratios, uint256 beanIndex, bool success) = LibWell.getRatiosAndBeanIndex(
            tokens
        );
        // If the USD Oracle oracle call fails, the convert should not be allowed.
        require(success, "Convert: USD Oracle failed");

        uint256 beansAtPeg = IBeanstalkWellFunction(wellFunction.target)
            .calcReserveAtRatioLiquidity(reserves, beanIndex, ratios, wellFunction.data);

        if (reserves[beanIndex] <= beansAtPeg) return 0;

        uint256 lpSupplyNow = IBeanstalkWellFunction(wellFunction.target).calcLpTokenSupply(
            reserves,
            wellFunction.data
        );

        reserves[beanIndex] = beansAtPeg;
        return
            lpSupplyNow.sub(
                IBeanstalkWellFunction(wellFunction.target).calcLpTokenSupply(
                    reserves,
                    wellFunction.data
                )
            );
    }

    /**
     * @dev Calculates the amount of Beans recieved from converting
     * `amountIn` LP Tokens of a given `well`.
     */
    function getBeanAmountOut(
        address well,
        uint256 amountIn
    ) internal view returns (uint256 beans) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        beans = IWell(well).getRemoveLiquidityOneTokenOut(amountIn, IERC20(s.sys.tokens.bean));
    }

    /**
     * @dev Calculates the amount of LP Tokens of a given `well` recieved from converting
     * `amountIn` Beans.
     */
    function getLPAmountOut(address well, uint256 amountIn) internal view returns (uint256 lp) {
        IERC20[] memory tokens = IWell(well).tokens();
        uint256[] memory amounts = new uint256[](tokens.length);
        amounts[LibWell.getBeanIndex(tokens)] = amountIn;
        lp = IWell(well).getAddLiquidityOut(amounts);
    }

    /**
     * @notice Converts `lp` LP Tokens of a given `well` into at least `minBeans` Beans
     * while ensuring that delta B <= 0 in the Well.
     * @param convertData Contains the encoding of `lp`, `minBeans` and `well`.
     * @return tokenOut The token to convert to.
     * @return tokenIn The token to convert from
     * @return amountOut The number of `tokenOut` convert to
     * @return amountIn The number of `tokenIn` converted from
     */
    function convertLPToBeans(
        bytes memory convertData
    ) internal returns (address tokenOut, address tokenIn, uint256 amountOut, uint256 amountIn) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        (uint256 lp, uint256 minBeans, address well) = convertData.convertWithAddress();

        require(LibWell.isWell(well), "Convert: Invalid Well");

        tokenOut = s.sys.tokens.bean;
        tokenIn = well;

        (amountOut, amountIn) = _wellRemoveLiquidityTowardsPeg(lp, minBeans, well);
    }

    /**
     * @dev Removes Liquidity as Beans with the constraint that delta B <= 0.
     */
    function _wellRemoveLiquidityTowardsPeg(
        uint256 lp,
        uint256 minBeans,
        address well
    ) internal returns (uint256 beans, uint256 lpConverted) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        uint256 maxLp = lpToPeg(well);
        require(maxLp > 0, "Convert: P must be < 1.");
        lpConverted = lp > maxLp ? maxLp : lp;
        beans = IWell(well).removeLiquidityOneToken(
            lpConverted,
            BeanstalkERC20(s.sys.tokens.bean),
            minBeans,
            address(this),
            block.timestamp
        );
    }

    /**
     * @notice Converts `beans` Beans into at least `minLP` LP Tokens of a given `well`
     * while ensuring that delta B >= 0 in the Well.
     * @param convertData Contains the encoding of `beans`, `minLp` and `well`.
     * @return tokenOut The token to convert to.
     * @return tokenIn The token to convert from
     * @return amountOut The number of `tokenOut` convert to
     * @return amountIn The number of `tokenIn` converted from
     */
    function convertBeansToLP(
        bytes memory convertData
    ) internal returns (address tokenOut, address tokenIn, uint256 amountOut, uint256 amountIn) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        (uint256 beans, uint256 minLP, address well) = convertData.convertWithAddress();

        require(LibWell.isWell(well), "Convert: Invalid Well");

        tokenOut = well;
        tokenIn = s.sys.tokens.bean;

        (amountOut, amountIn) = _wellAddLiquidityTowardsPeg(beans, minLP, well);
    }

    /**
     * @dev Adds as Beans Liquidity with the constraint that delta B >= 0.
     */
    function _wellAddLiquidityTowardsPeg(
        uint256 beans,
        uint256 minLP,
        address well
    ) internal returns (uint256 lp, uint256 beansConverted) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        (uint256 maxBeans, ) = _beansToPeg(well);
        require(maxBeans > 0, "Convert: P must be >= 1.");
        beansConverted = beans > maxBeans ? maxBeans : beans;
        BeanstalkERC20(s.sys.tokens.bean).transfer(well, beansConverted);
        lp = IWell(well).sync(address(this), minLP);
    }
}

