            if (absTick & 0x20000 != 0) ratio = (ratio * 0x5d6af8dedb81196699c329225ee604) >> 128;
            if (absTick & 0x40000 != 0) ratio = (ratio * 0x2216e584f5fa1ea926041bedfe98) >> 128;
            if (absTick & 0x80000 != 0) ratio = (ratio * 0x48a170391f7dc42444e8fa2) >> 128;

            if (tick > 0) ratio = type(uint256).max / ratio;

            // this divides by 1<<32 rounding up to go from a Q128.128 to a Q128.96.
            // we then downcast because we know the result always fits within 160 bits due to our tick input constraint
            // we round up in the division so getTickAtSqrtRatio of the output price is always consistent
            sqrtPriceX96 = uint160((ratio >> 32) + (ratio % (1 << 32) == 0 ? 0 : 1));
        }
    }

    /// @notice Calculates the greatest tick value such that getRatioAtTick(tick) <= ratio
    /// @dev Throws in case sqrtPriceX96 < MIN_SQRT_RATIO, as MIN_SQRT_RATIO is the lowest value getRatioAtTick may
    /// ever return.
    /// @param sqrtPriceX96 The sqrt ratio for which to compute the tick as a Q64.96
    /// @return tick The greatest tick for which the ratio is less than or equal to the input ratio
    function getTickAtSqrtRatio(uint160 sqrtPriceX96) internal pure returns (int24 tick) {
        unchecked {
            // second inequality must be < because the price can never reach the price at the max tick
            if (!(sqrtPriceX96 >= MIN_SQRT_RATIO && sqrtPriceX96 < MAX_SQRT_RATIO)) revert R();
            uint256 ratio = uint256(sqrtPriceX96) << 32;

            uint256 r = ratio;
            uint256 msb = 0;

            assembly {
                let f := shl(7, gt(r, 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(6, gt(r, 0xFFFFFFFFFFFFFFFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(5, gt(r, 0xFFFFFFFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(4, gt(r, 0xFFFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(3, gt(r, 0xFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(2, gt(r, 0xF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(1, gt(r, 0x3))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := gt(r, 0x1)
                msb := or(msb, f)
            }

            if (msb >= 128) r = ratio >> (msb - 127);
            else r = ratio << (127 - msb);

            int256 log_2 = (int256(msb) - 128) << 64;

            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(63, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(62, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(61, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(60, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(59, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(58, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(57, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(56, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(55, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(54, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(53, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(52, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(51, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(50, f))
            }

            int256 log_sqrt10001 = log_2 * 255738958999603826347141; // 128.128 number

            int24 tickLow = int24((log_sqrt10001 - 3402992956809132418596140100660247210) >> 128);
            int24 tickHi = int24((log_sqrt10001 + 291339464771989622907027621153398088495) >> 128);

            tick = tickLow == tickHi ? tickLow : getSqrtRatioAtTick(tickHi) <= sqrtPriceX96 ? tickHi : tickLow;
        }
    }
}

contracts/beanstalk/field/FieldFacet.sol.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {C} from "contracts/C.sol";
import {LibRedundantMath32} from "contracts/libraries/LibRedundantMath32.sol";
import {LibRedundantMath128} from "contracts/libraries/LibRedundantMath128.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibTractor} from "contracts/libraries/LibTractor.sol";
import {LibTransfer} from "contracts/libraries/Token/LibTransfer.sol";
import {LibDibbler} from "contracts/libraries/LibDibbler.sol";
import {ReentrancyGuard} from "../ReentrancyGuard.sol";
import {Invariable} from "contracts/beanstalk/Invariable.sol";
import {LibDiamond} from "contracts/libraries/LibDiamond.sol";
import {LibMarket} from "contracts/libraries/LibMarket.sol";
import {BeanstalkERC20} from "contracts/tokens/ERC20/BeanstalkERC20.sol";

interface IBeanstalk {
    function cancelPodListing(uint256 fieldId, uint256 index) external;
}

/**
 * @title FieldFacet
 * @author Publius, Brean
 * @notice The Field is where Beans are Sown and Pods are Harvested.
 */
contract FieldFacet is Invariable, ReentrancyGuard {
    using LibRedundantMath256 for uint256;
    using LibRedundantMath32 for uint32;
    using LibRedundantMath128 for uint128;

    /**
     * @notice Plot struct contains the plot index and amount of pods the plot contains.
     */
    struct Plot {
        uint256 index;
        uint256 pods;
    }

    /**
     * @notice Emitted when a new Field is added.
     * @param fieldId The index of the Field that was added.
     */
    event FieldAdded(uint256 fieldId);

    /**
     * @notice Emitted when the active Field is modified.
     * @param fieldId The index of the Field that was set to active.
     */
    event ActiveFieldSet(uint256 fieldId);

    /**
     * @notice Emitted from {LibDibbler.sow} when an `account` creates a plot.
     * A Plot is a set of Pods created in from a single {sow} or {fund} call.
     * @param account The account that sowed Beans for Pods
     * @param index The place in line of the Plot
     * @param beans The amount of Beans burnt to create the Plot
     * @param pods The amount of Pods assocated with the created Plot
     */
    event Sow(address indexed account, uint256 fieldId, uint256 index, uint256 beans, uint256 pods);

    /**
     * @notice Emitted when `account` claims the Beans associated with Harvestable Pods.
     * @param account The account that owns the `plots`
     * @param plots The indices of Plots that were harvested
     * @param beans The amount of Beans transferred to `account`
     */
    event Harvest(address indexed account, uint256 fieldId, uint256[] plots, uint256 beans);

    //////////////////// SOW ////////////////////

    /**
     * @notice Sow Beans in exchange for Pods.
     * @param beans The number of Beans to Sow
     * @param minTemperature The minimum Temperature at which to Sow
     * @param mode The balance to transfer Beans from; see {LibTransfer.From}
     * @return pods The number of Pods received
     * @dev
     *
     * `minTemperature` has precision of 1e6. Wraps {sowWithMin} with `minSoil = beans`.
     *
     * NOTE: previously minTemperature was measured to 1e2 (1% = 1)
     *
     * Rationale for {sow} accepting a `minTemperature` parameter:
     * If someone sends a Sow transaction at the end of a Season, it could be
     * executed early in the following Season, at which time the temperature may be
     * significantly lower due to Morning Auction functionality.
     */
    function sow(
        uint256 beans,
        uint256 minTemperature,
        LibTransfer.From mode
    )
        external
        payable
        fundsSafu
        noSupplyIncrease
        oneOutFlow(s.sys.tokens.bean)
        nonReentrant
        returns (uint256 pods)
    {
        return LibDibbler.sowWithMin(beans, minTemperature, beans, mode);
    }

    /**
     * @notice Sow Beans in exchange for Pods. Use at least `minSoil`.
     * @param beans The number of Beans to Sow
     * @param minTemperature The minimum Temperature at which to Sow
     * @param minSoil The minimum amount of Soil to use; reverts if there is
     * less than this much Soil available upon execution
     * @param mode The balance to transfer Beans from; see {LibTrasfer.From}
     * @return pods The number of Pods received
     */
    function sowWithMin(
        uint256 beans,
        uint256 minTemperature,
        uint256 minSoil,
        LibTransfer.From mode
    )
        external
        payable
        fundsSafu
        noSupplyIncrease
        oneOutFlow(s.sys.tokens.bean)
        nonReentrant
        returns (uint256 pods)
    {
        return LibDibbler.sowWithMin(beans, minTemperature, minSoil, mode);
    }

    //////////////////// HARVEST ////////////////////

    /**
     * @notice Harvest Pods from the Field.
     * @param fieldId The index of the Field to Harvest from.
     * @param plots List of plot IDs to Harvest
     * @param mode The balance to transfer Beans to; see {LibTrasfer.To}
     * @dev Redeems Pods for Beans. When Pods become Harvestable, they are
     * redeemable for 1 Bean each.
     *
     * The Beans used to pay Harvestable Pods are minted during {Sun.stepSun}.
     * Beanstalk holds these Beans until `harvest()` is called.
     *
     * Pods are "burned" when the corresponding Plot is deleted from
     * `s.accts[account].fields[fieldId].plots`.
     */
    function harvest(
        uint256 fieldId,
        uint256[] calldata plots,
        LibTransfer.To mode
    ) external payable fundsSafu noSupplyChange oneOutFlow(s.sys.tokens.bean) nonReentrant {
        uint256 beansHarvested = _harvest(fieldId, plots);
        LibTransfer.sendToken(
            BeanstalkERC20(s.sys.tokens.bean),
            beansHarvested,
            LibTractor._user(),
            mode
        );
    }

    /**
     * @dev Ensure that each Plot is at least partially harvestable, burn the Plot,
     * update the total harvested, and emit a {Harvest} event.
     */
    function _harvest(
        uint256 fieldId,
        uint256[] calldata plots
    ) internal returns (uint256 beansHarvested) {
        for (uint256 i; i < plots.length; ++i) {
            // The Plot is partially harvestable if its index is less than
            // the current harvestable index.
            require(plots[i] < s.sys.fields[fieldId].harvestable, "Field: Plot not Harvestable");
            uint256 harvested = _harvestPlot(LibTractor._user(), fieldId, plots[i]);
            beansHarvested += harvested;
        }
        s.sys.fields[fieldId].harvested += beansHarvested;
        emit Harvest(LibTractor._user(), fieldId, plots, beansHarvested);
    }

    /**
     * @dev Check if a Plot is at least partially Harvestable; calculate how many
     * Pods are Harvestable, create a new Plot if necessary.
     */
    function _harvestPlot(
        address account,
        uint256 fieldId,
        uint256 index
    ) private returns (uint256 harvestablePods) {
        // Check that `account` holds this Plot.
        uint256 pods = s.accts[account].fields[fieldId].plots[index];
        require(pods > 0, "Field: no plot");

        // Calculate how many Pods are harvestable.
        // The upstream _harvest function checks that at least some Pods
        // are harvestable.
        harvestablePods = s.sys.fields[fieldId].harvestable.sub(index);

        LibMarket._cancelPodListing(LibTractor._user(), fieldId, index);

        delete s.accts[account].fields[fieldId].plots[index];
        LibDibbler.removePlotIndexFromAccount(account, fieldId, index);

        // If the entire Plot was harvested, exit.
        if (harvestablePods >= pods) {
            return pods;
        }

        // Create a new Plot with remaining Pods.
        uint256 newIndex = index.add(harvestablePods);
        s.accts[account].fields[fieldId].plots[newIndex] = pods.sub(harvestablePods);
        s.accts[account].fields[fieldId].plotIndexes.push(newIndex);
        s.accts[account].fields[fieldId].piIndex[newIndex] =
            s.accts[account].fields[fieldId].plotIndexes.length -
            1;
    }

    //////////////////// CONFIG /////////////////////

    /**
     * @notice Add a new Field to the system.
     * @dev It is not possible to remove a Field, but a Field's Plan can be nullified.
     */
    function addField() public fundsSafu noSupplyChange noNetFlow nonReentrant {
        LibDiamond.enforceIsOwnerOrContract();
        uint256 fieldId = s.sys.fieldCount;
        s.sys.fieldCount++;
        emit FieldAdded(fieldId);
    }

    /**
     * @notice Set the active Field. Only the active field is accrues Soil.
     * @param fieldId ID of the Field to set as active. ID is the Field Number.
     */
    function setActiveField(
        uint256 fieldId,
        uint32 _temperature
    ) public fundsSafu noSupplyChange noNetFlow nonReentrant {
        LibDiamond.enforceIsOwnerOrContract();
        require(fieldId < s.sys.fieldCount, "Field: Field does not exist");
        s.sys.activeField = fieldId;

        // Reset weather.
        s.sys.weather.temp = _temperature;
        s.sys.weather.thisSowTime = type(uint32).max;
        s.sys.weather.lastSowTime = type(uint32).max;
        s.sys.weather.lastDeltaSoil = 0;

        emit ActiveFieldSet(fieldId);
    }

    //////////////////// GETTERS ////////////////////

    /**
     * @notice Returns the total number of Pods ever minted in the Field.
     * @param fieldId The index of the Field to query.
     */
    function podIndex(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].pods;
    }

    /**
     * @notice Returns the index below which Pods are Harvestable.
     * @param fieldId The index of the Field to query.
     */
    function harvestableIndex(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].harvestable;
    }

    /**
     * @notice Returns the number of outstanding Pods. Includes Pods that are
     * currently Harvestable but have not yet been Harvested.
     * @param fieldId The index of the Field to query.
     */
    function totalPods(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].pods - s.sys.fields[fieldId].harvested;
    }

    /**
     * @notice Returns the number of Pods that have ever been Harvested.
     * @param fieldId The index of the Field to query.
     */
    function totalHarvested(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].harvested;
    }

    /**
     * @notice Returns the number of Pods that are currently Harvestable but
     * have not yet been Harvested.
     * @dev This is the number of Pods that Beanstalk is prepared to pay back,
     * but that haven’t yet been claimed via the `harvest()` function.
     * @param fieldId The index of the Field to query.
     */
    function totalHarvestable(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].harvestable - s.sys.fields[fieldId].harvested;
    }

    /**
     * @notice Returns the number of Pods that are currently Harvestable for the active Field.
     */
    function totalHarvestableForActiveField() public view returns (uint256) {
        return
            s.sys.fields[s.sys.activeField].harvestable - s.sys.fields[s.sys.activeField].harvested;
    }

    /**
     * @notice Returns the number of Pods that are not yet Harvestable. Also known as the Pod Line.
     * @param fieldId The index of the Field to query.
     */
    function totalUnharvestable(uint256 fieldId) public view returns (uint256) {
        return s.sys.fields[fieldId].pods - s.sys.fields[fieldId].harvestable;
    }

    /**
     * @notice Returns true if there exists un-harvestable pods.
     * @param fieldId The index of the Field to query.
     */
    function isHarvesting(uint256 fieldId) public view returns (bool) {
        return totalUnharvestable(fieldId) > 0;
    }

    /**
     * @notice Returns the number of Pods remaining in a Plot.
     * @dev Plots are only stored in the `s.accts[account].fields[fieldId].plots` mapping.
     * @param fieldId The index of the Field to query.
     */
    function plot(address account, uint256 fieldId, uint256 index) public view returns (uint256) {
        return s.accts[account].fields[fieldId].plots[index];
    }

    function activeField() public view returns (uint256) {
        return s.sys.activeField;
    }

    function fieldCount() public view returns (uint256) {
        return s.sys.fieldCount;
    }

    //////////////////// GETTERS: SOIL ////////////////////

    /**
     * @notice Returns the total amount of available Soil. 1 Bean can be Sown in
     * 1 Soil for Pods.
     * @dev When above peg, Soil is dynamic because the number of Pods that
     * Beanstalk is willing to mint is fixed.
     */
    function totalSoil() external view returns (uint256) {
        // Below peg: Soil is fixed to the amount set during {calcCaseId}.
        if (!s.sys.season.abovePeg) {
            return uint256(s.sys.soil);
        }

        // Above peg: Soil is dynamic
        return
            LibDibbler.scaleSoilUp(
                uint256(s.sys.soil), // min soil
                uint256(s.sys.weather.temp).mul(LibDibbler.TEMPERATURE_PRECISION), // max temperature
                LibDibbler.morningTemperature() // temperature adjusted by number of blocks since Sunrise
            );
    }

    //////////////////// GETTERS: TEMPERATURE ////////////////////

    /**
     * @notice Returns the current Temperature, the interest rate offered by Beanstalk.
     * The Temperature scales up during the first 25 blocks after Sunrise.
     */
    function temperature() external view returns (uint256) {
        return LibDibbler.morningTemperature();
    }

    /**
     * @notice Returns the max Temperature that Beanstalk is willing to offer this Season.
     * @dev For gas efficiency, Beanstalk stores `s.weather.t` as a uint32 with precision of 1e2.
     * Here we convert to uint256 and scale up by TEMPERATURE_PRECISION to match the
     * precision needed for the Morning Auction functionality.
     */
    function maxTemperature() external view returns (uint256) {
        return uint256(s.sys.weather.temp).mul(LibDibbler.TEMPERATURE_PRECISION);
    }

    //////////////////// GETTERS: PODS ////////////////////

    /**
     * @notice Returns the remaining Pods that could be issued this Season.
     */
    function remainingPods() external view returns (uint256) {
        return uint256(LibDibbler.remainingPods());
    }

    /**
     * @notice returns the plotIndexes owned by `account`.
     */
    function getPlotIndexesFromAccount(
        address account,
        uint256 fieldId
    ) external view returns (uint256[] memory plotIndexes) {
        return s.accts[account].fields[fieldId].plotIndexes;
    }

    /**
     * @notice returns the plots owned by `account`.
     */
    function getPlotsFromAccount(
        address account,
        uint256 fieldId
    ) external view returns (Plot[] memory plots) {
        uint256[] memory plotIndexes = s.accts[account].fields[fieldId].plotIndexes;
        if (plotIndexes.length == 0) return plots;
        plots = new Plot[](plotIndexes.length);
        for (uint256 i = 0; i < plotIndexes.length; i++) {
            uint256 index = plotIndexes[i];
            plots[i] = Plot(index, s.accts[account].fields[fieldId].plots[index]);
        }
    }

    /**
     * @notice returns the number of pods owned by `account` in a field.
     */
    function balanceOfPods(address account, uint256 fieldId) external view returns (uint256 pods) {
        uint256[] memory plotIndexes = s.accts[account].fields[fieldId].plotIndexes;
        for (uint256 i = 0; i < plotIndexes.length; i++) {
            pods += s.accts[account].fields[fieldId].plots[plotIndexes[i]];
        }
    }
}

contracts/beanstalk/Invariable.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibRedundantMathSigned256} from "contracts/libraries/LibRedundantMathSigned256.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {GerminationSide} from "contracts/beanstalk/storage/System.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibUnripe} from "contracts/libraries/LibUnripe.sol";
import {BeanstalkERC20} from "contracts/tokens/ERC20/BeanstalkERC20.sol";

/**
 * @author funderbrker
 * @title Invariable
 * @notice Implements modifiers that maintain protocol wide invariants.
 * @dev Every external writing function should use as many non-redundant invariant modifiers as possible.
 * @dev https://www.nascent.xyz/idea/youre-writing-require-statements-wrong
 **/
abstract contract Invariable {
    using LibRedundantMath256 for uint256;
    using LibRedundantMathSigned256 for int256;
    using SafeCast for uint256;

    /**
     * @notice Ensures all user asset entitlements are coverable by contract balances.
     * @dev Should be used on every function that can write. Excepting Diamond functions.
     */
    modifier fundsSafu() {
        _;
        address[] memory tokens = getTokensOfInterest();
        (
            uint256[] memory entitlements,
            uint256[] memory balances
        ) = getTokenEntitlementsAndBalances(tokens);
        for (uint256 i; i < tokens.length; i++) {
            require(balances[i] >= entitlements[i], "INV: Insufficient token balance");
        }
    }

    /**
     * @notice Watched token balances do not change and Stalk does not decrease.
     * @dev Applicable to the majority of functions, excepting functions that explicitly move assets.
     * @dev Roughly akin to a view only check where only routine modifications are allowed (ie mowing).
     */
    modifier noNetFlow() {
        uint256 initialStalk = LibAppStorage.diamondStorage().sys.silo.stalk;
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        require(
            LibAppStorage.diamondStorage().sys.silo.stalk >= initialStalk,
            "INV: noNetFlow Stalk decreased"
        );
        for (uint256 i; i < tokens.length; i++) {
            require(
                initialProtocolTokenBalances[i] == finalProtocolTokenBalances[i],
                "INV: noNetFlow Token balance changed"
            );
        }
    }

    /**
     * @notice Watched token balances do not decrease and Stalk does not decrease.
     * @dev Favor noNetFlow where applicable.
     */
    modifier noOutFlow() {
        uint256 initialStalk = LibAppStorage.diamondStorage().sys.silo.stalk;
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        require(
            LibAppStorage.diamondStorage().sys.silo.stalk >= initialStalk,
            "INV: noOutFlow Stalk decreased"
        );
        for (uint256 i; i < tokens.length; i++) {
            require(
                initialProtocolTokenBalances[i] <= finalProtocolTokenBalances[i],
                "INV: noOutFlow Token balance decreased"
            );
        }
    }

    /**
     * @notice All except one watched token balances do not decrease.
     * @dev Favor noNetFlow or noOutFlow where applicable.
     */
    modifier oneOutFlow(address outboundToken) {
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        for (uint256 i; i < tokens.length; i++) {
            if (tokens[i] == outboundToken) {
                continue;
            }
            require(
                initialProtocolTokenBalances[i] <= finalProtocolTokenBalances[i],
                "INV: oneOutFlow multiple token balances decreased"
            );
        }
    }

    /**
     * @notice Does not change the supply of Beans. No minting, no burning.
     * @dev Applies to all but a very few functions tht explicitly change supply.
     */
    modifier noSupplyChange() {
        // Storage is not defined due to stack too deep errors.
        uint256 initialSupply = BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean)
            .totalSupply();
        _;
        require(
            BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean).totalSupply() ==
                initialSupply,
            "INV: Supply changed"
        );
    }

    /**
     * @notice Supply of Beans does not increase. No minting.
     * @dev Prefer noSupplyChange where applicable.
     */
    modifier noSupplyIncrease() {
        uint256 initialSupply = BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean)
            .totalSupply();
        _;
        require(
            BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean).totalSupply() <=
                initialSupply,
            "INV: Supply increased"
        );
    }

    /**
     * @notice Which tokens to monitor in the invariants.
     */
    function getTokensOfInterest() internal view returns (address[] memory tokens) {
        address[] memory whitelistedTokens = LibWhitelistedTokens.getWhitelistedTokens();
        address[] memory sopTokens = LibWhitelistedTokens.getSopTokens();
        uint256 totalLength = whitelistedTokens.length + sopTokens.length;
        tokens = new address[](totalLength);

        for (uint256 i = 0; i < whitelistedTokens.length; i++) {
            tokens[i] = whitelistedTokens[i];
        }

        for (uint256 i = 0; i < sopTokens.length; i++) {
            tokens[whitelistedTokens.length + i] = sopTokens[i];
        }
    }

    /**
     * @notice Get the Beanstalk balance of an ERC20 token.
     */
    function getTokenBalances(
        address[] memory tokens
    ) internal view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i; i < tokens.length; i++) {
            balances[i] = IERC20(tokens[i]).balanceOf(address(this));
        }
        return balances;
    }

    /**
     * @notice Get protocol level entitlements and balances for all tokens.
     */
    function getTokenEntitlementsAndBalances(
        address[] memory tokens
    ) internal view returns (uint256[] memory entitlements, uint256[] memory balances) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        entitlements = new uint256[](tokens.length);
        balances = new uint256[](tokens.length);

        for (uint256 i; i < tokens.length; i++) {
            entitlements[i] =
                s.sys.silo.balances[tokens[i]].deposited +
                s.sys.silo.germinating[GerminationSide.ODD][tokens[i]].amount +
                s.sys.silo.germinating[GerminationSide.EVEN][tokens[i]].amount +
                s.sys.internalTokenBalanceTotal[IERC20(tokens[i])];
            if (tokens[i] == s.sys.tokens.bean) {
                entitlements[i] +=
                    (s.sys.fert.fertilizedIndex -
                        s.sys.fert.fertilizedPaidIndex +
                        s.sys.fert.leftoverBeans) + // unrinsed rinsable beans
                    s.sys.silo.unripeSettings[s.sys.tokens.urBean].balanceOfUnderlying + // unchopped underlying beans
                    s.sys.orderLockedBeans;
                for (uint256 j; j < s.sys.fieldCount; j++) {
                    entitlements[i] += (s.sys.fields[j].harvestable - s.sys.fields[j].harvested); // unharvested harvestable beans
                }
            } else if (tokens[i] == LibUnripe._getUnderlyingToken(s.sys.tokens.urLp)) {
                entitlements[i] += s.sys.silo.unripeSettings[s.sys.tokens.urLp].balanceOfUnderlying;
            }
            entitlements[i] += s.sys.sop.plentyPerSopToken[tokens[i]];
            balances[i] = IERC20(tokens[i]).balanceOf(address(this));
        }
        return (entitlements, balances);
    }
}

contracts/beanstalk/ReentrancyGuard.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {AppStorage} from "./storage/AppStorage.sol";
import {C} from "contracts/C.sol";

/**
 * @author Beanstalk Farms
 * @title Variation of Oepn Zeppelins reentrant guard to include Beanstalk specific functionality.
 * https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts%2Fsecurity%2FReentrancyGuard.sol
 *
 * The key difference between Beanstalk reentrancy and standard reentrancy is the need for Beanstalk
 * to be able to re-enter itself executing functions through farm-like functions. This Farm functiiionality
 * allows users to batch multiple Beanstalk functions into a single transaction.
 * Examples of Farm use can be seen in Farm, AdvancedFarm, Tractor, and PipelineConvert.
 * Reference _beanstalkCall() to see Farm interaction with ReentrancyGuard.
 **/
abstract contract ReentrancyGuard {
    AppStorage internal s;

    /**
     * @notice Verify Beanstalk is not already entered and lock entrance.
     * @dev Standard reentrancy is not compatible with farm-like features.
     */
    modifier nonReentrant() {
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }

    /**
     * @notice Verify and lock both standard entrance and farming entrance.
     * @dev This modifier should be used on all functions that contain generalized Farm calls.
     */
    modifier nonReentrantFarm() {
        require(s.sys.farmingStatus != C.ENTERED, "ReentrancyGuard: reentrant farm call");
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.farmingStatus = C.ENTERED;
        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.farmingStatus = C.NOT_ENTERED;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }
}

contracts/beanstalk/storage/Account.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {GerminationSide} from "./System.sol";

/**
 * @title Account
 * @notice Stores Farmer-level Beanstalk state.
 * @param roots A Farmer's Root balance.
 * @param stalk Balance of the Farmer's Stalk.
 * @param depositPermitNonces A Farmer's current deposit permit nonce.
 * @param tokenPermitNonces A Farmer's current token permit nonce.
 * @param lastUpdate The Season in which the Farmer last updated their Silo.
 * @param lastSop The last Season that a SOP occurred at the time the Farmer last updated their Silo.
 * @param lastRain The last Season that it started Raining at the time the Farmer last updated their Silo.
 * @param _buffer_0 Reserved storage for future additions.
 * @param deposits SiloV3.1 deposits. A mapping from depositId to Deposit. SiloV3.1 introduces greater precision for deposits.
 * @param depositIdList DepositListData for each token owned by the account.
 * @param field A mapping from FieldId to a Farmer's Field storage.
 * @param depositAllowances A mapping of `spender => Silo token address => amount`.
 * @param tokenAllowances Internal balance token allowances.
 * @param mowStatuses A mapping of whitelisted token address to MowStatus.
 * @param isApprovedForAll A mapping of ERC1155 operator to approved status. ERC1155 compatability.
 * @param germinatingStalk A Farmer's germinating stalk. Separated into odd and even stalk.
 * @param internalTokenBalance A mapping from Token address to Internal Balance. It stores the amount of the Token that the Farmer has stored as an Internal Balance in Beanstalk.
 * @param _buffer_1 Reserved storage for future additions.
 * @param silo A Farmer's Silo storage.
 * @param sop A Farmer's Season of Plenty storage.
 */
struct Account {
    uint256 roots;
    uint256 stalk;
    uint256 depositPermitNonces;
    uint256 tokenPermitNonces;
    uint32 lastUpdate;
    uint32 lastSop;
    uint32 lastRain;
    bytes32[16] _buffer_0;
    mapping(uint256 => Deposit) deposits;
    mapping(address => DepositListData) depositIdList;
    mapping(uint256 => Field) fields;
    mapping(address => mapping(address => uint256)) depositAllowances;
    mapping(address => mapping(IERC20 => uint256)) tokenAllowances;
    mapping(address => MowStatus) mowStatuses;
    mapping(address => bool) isApprovedForAll;
    mapping(GerminationSide => uint128) germinatingStalk;
    mapping(IERC20 => uint256) internalTokenBalance;
    bytes32[16] _buffer_1;
    SeasonOfPlenty sop;
}

/**
 * @notice Stores a Farmer's Plots and Pod allowances.
 * @param plots A Farmer's Plots. Maps from Plot index to Pod amount.
 * @param podAllowances An allowance mapping for Pods similar to that of the ERC-20 standard. Maps from spender address to allowance amount.
 * @param plotIndexes An array of Plot indexes. Used to return the farm plots of a Farmer.
 * @param piIndex A mapping from Plot index to the index in plotIndexes.
 * @param _buffer Reserved storage for future additions.
 */
struct Field {
    mapping(uint256 => uint256) plots;
    mapping(address => uint256) podAllowances;
    uint256[] plotIndexes;
    mapping(uint256 => uint256) piIndex;
    bytes32[4] _buffer;
}

/**
 * @notice Stores a Farmer's Season of Plenty (SOP) balances.
 * @param roots The number of Roots a Farmer had when it started Raining.
 * @param plentyPerRoot The global Plenty Per Root index at the last time a Farmer updated their Silo.
 * @param plenty The balance of a Farmer's plenty. Plenty can be claimed directly for tokens.
 * @param _buffer Reserved storage for future additions.
 */
struct SeasonOfPlenty {
    uint256 rainRoots; // The number of Roots a Farmer had when it started Raining.
    mapping(address => PerWellPlenty) perWellPlenty; // a mapping from well to plentyPerRoot and plenty.
    bytes32[4] _buffer;
}

/**
 * @notice Stores a Farmer's Season of Plenty (SOP) balances.
 * @param plentyPerRoot The Plenty Per Root index for this well at the last time a Farmer updated their Silo.
 * @param plenty The balance of a Farmer's plenty. Plenty can be claimed directly for the well's non-Bean token.
 */
struct PerWellPlenty {
    uint256 plentyPerRoot;
    uint256 plenty;
    bytes32[4] _buffer;
}

/**
 * @notice Represents a Deposit of a given Token in the Silo at a given Season.
 * @param amount The amount of Tokens in the Deposit.
 * @param bdv The Bean-denominated value of the total amount of Tokens in the Deposit.
 * @param _buffer Reserved storage for future additions.
 * @dev `amount` and `bdv` are packed as uint128 to save gas.
 */
struct Deposit {
    uint128 amount;
    uint128 bdv;
}

/**
 * @notice Stores a Farmer's germinating stalk.
 * @param odd - stalk from assets deposited in odd seasons.
 * @param even - stalk from assets deposited in even seasons.
 * @param _buffer Reserved storage for future additions.
 */
struct GerminatingStalk {
    uint128 odd;
    uint128 even;
}

/**
 * @notice This struct stores the mow status for each whitelisted token, for each farmer.
 * This gets updated each time a farmer mows, or adds/removes deposits.
 * @param lastStem The last cumulative grown stalk per bdv index at which the farmer mowed.
 * @param bdv The bdv of all of a farmer's deposits of this token type.
 * @param _buffer Reserved storage for future additions.
 */
struct MowStatus {
    int96 lastStem;
    uint128 bdv;
}

/**
 * @notice This struct stores data for a deposit list for a given token.
 * a mapping from id to index was created to allow for O(1) retrevial of a deposit from the list.
 * @param depositIds An array of depositIds for a given token.
 * @param idIndex A mapping from depositId to index in depositIds.
 */
struct DepositListData {
    uint256[] depositIds;
    mapping(uint256 => uint256) idIndex;
}

