                            return 0.5424140302842413e18; // 1,000,000, 0.29
                        } else {
                            return 0.5635119158156667e18; // 1,000,000, 0.27
                        }
                    } else {
                        if (recapPercentPaid > 0.23e6) {
                            return 0.5857864256253713e18; // 1,000,000, 0.25
                        } else {
                            return 0.6093112868361505e18; // 1,000,000, 0.23
                        }
                    }
                } else {
