contracts/libraries/Token/LibTokenApprov.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibAppStorage} from "../LibAppStorage.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";

/**
 * @title LibTokenApprove
 * @author Publius
 */
library LibTokenApprove {
    event TokenApproval(
        address indexed owner,
        address indexed spender,
        IERC20 token,
        uint256 amount
    );

    function approve(address account, address spender, IERC20 token, uint256 amount) internal {
        AppStorage storage s = LibAppStorage.diamondStorage();
        s.accts[account].tokenAllowances[spender][token] = amount;
        emit TokenApproval(account, spender, token, amount);
    }

    function allowance(
        address account,
        address spender,
        IERC20 token
    ) internal view returns (uint256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return s.accts[account].tokenAllowances[spender][token];
    }

    function spendAllowance(address owner, address spender, IERC20 token, uint256 amount) internal {
        uint256 currentAllowance = allowance(owner, spender, token);
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "Token: insufficient allowance");
            approve(owner, spender, token, currentAllowance - amount);
        }
    }
}

contracts/libraries/Token/LibTokenPermit.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "../../C.sol";
import "../LibAppStorage.sol";

/**
 * @author Publius
 * @title Lib Silo Permit
 **/
library LibTokenPermit {
    bytes32 private constant TOKEN_PERMIT_HASHED_NAME = keccak256(bytes("Token"));
    bytes32 private constant TOKEN_PERMIT_HASHED_VERSION = keccak256(bytes("1"));
    bytes32 private constant TOKEN_PERMIT_EIP712_TYPE_HASH =
        keccak256(
            "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
        );
    bytes32 private constant TOKEN_PERMIT_TYPEHASH =
        keccak256(
            "Permit(address owner,address spender,address token,uint256 value,uint256 nonce,uint256 deadline)"
        );

    function permit(
        address owner,
        address spender,
        address token,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) internal {
        require(block.timestamp <= deadline, "Token: permit expired deadline");
        bytes32 structHash = keccak256(
            abi.encode(
                TOKEN_PERMIT_TYPEHASH,
                owner,
                spender,
                token,
                value,
                _useNonce(owner),
                deadline
            )
        );
        bytes32 hash = _hashTypedDataV4(structHash);
        address signer = ECDSA.recover(hash, v, r, s);
        require(signer == owner, "Token: permit invalid signature");
    }

    function nonces(address owner) internal view returns (uint256) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        return s.accts[owner].tokenPermitNonces;
    }

    function _useNonce(address owner) internal returns (uint256 current) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        current = s.accts[owner].tokenPermitNonces;
        ++s.accts[owner].tokenPermitNonces;
    }

    /**
     * @dev Returns the domain separator for the current chain.
     */
    function _domainSeparatorV4() internal view returns (bytes32) {
        return
            _buildDomainSeparator(
                TOKEN_PERMIT_EIP712_TYPE_HASH,
                TOKEN_PERMIT_HASHED_NAME,
                TOKEN_PERMIT_HASHED_VERSION
            );
    }

    function _buildDomainSeparator(
        bytes32 typeHash,
        bytes32 name,
        bytes32 version
    ) internal view returns (bytes32) {
        return keccak256(abi.encode(typeHash, name, version, block.chainid, address(this)));
    }

    /**
     * @dev Given an already https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct[hashed struct], this
     * function returns the hash of the fully encoded EIP712 message for this domain.
     *
     * This hash can be used together with {ECDSA-recover} to obtain the signer of a message. For example:
     *
     * ```solidity
     * bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(
     *     keccak256("Mail(address to,string contents)"),
     *     mailTo,
     *     keccak256(bytes(mailContents))
     * )));
     * address signer = ECDSA.recover(digest, signature);
     * ```
     */
    function _hashTypedDataV4(bytes32 structHash) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", _domainSeparatorV4(), structHash));
    }
}

